    INSERT INTO mcqs (topic_id, question, options, correct_index, explanation) VALUES
    (v_topic_id, '1: A patient is brought to the ER by police after running into traffic, screaming that angels told him to fly. Can he be involuntarily hospitalized?', '["No, he has the right to refuse", "Yes, he meets the criteria for involuntary hold (danger to self/others or gravely disabled due to mental illness)", "Only if a judge is present", "None"]', 1, 'Involuntary hold (e.g., 5150 in CA) is justified if the patient is a danger to themselves, others, or gravely disabled. (Kaplan & Sadock)'),
    (v_topic_id, '2: What is "Tarasoff Duty"?', '["Duty to treat", "The duty of a psychiatrist to warn or protect a specifically identified third party who is threatened with violence by a patient", "Duty to report child abuse", "None"]', 1, 'Stemming from Tarasoff v. Regents of the University of California. (First Aid)'),
    (v_topic_id, '3: A patient says, "I hate my boss. Someday someone is going to kill him." Does this trigger Tarasoff duty?', '["Yes", "No, there is no specific, imminent threat made BY the patient against the boss", "Only if the boss is a public figure", "None"]', 1, 'The threat must be specific, imminent, and plausible. (MGH Pocket)'),
    (v_topic_id, '4: A patient says, "I bought a gun and I am going to shoot my ex-wife at her office tomorrow at noon." Does this trigger Tarasoff?', '["Yes, you must act to warn/protect the ex-wife and notify police", "No, confidentiality is absolute", "Only if she asks", "None"]', 0, 'This is a clear, specific, and imminent threat. You must break confidentiality. (First Aid)'),
    (v_topic_id, '5: Which of the following overrides psychiatric confidentiality?', '["A spouse asking for records", "Suspected child abuse or elder abuse", "An employer asking for a drug test result", "None"]', 1, 'Mandatory reporting laws for vulnerable populations override HIPAA/confidentiality. (Kaplan & Sadock)'),
    (v_topic_id, '6: A 16-year-old girl tells her psychiatrist she is pregnant and asks for an abortion referral, begging the doctor not to tell her parents. What is the doctor''s obligation?', '["Must tell the parents immediately", "Depends on state law, but generally minors have the right to confidential care regarding pregnancy, contraception, and STDs", "Must call child protective services", "None"]', 1, 'Emancipated/mature minor exceptions apply to reproductive health in most states. (First Aid)'),
    (v_topic_id, '7: What defines "Capacity" in a medical setting?', '["A legal determination made by a judge", "A clinical determination made by a physician regarding a patient''s ability to understand, appreciate, reason, and communicate a choice about a specific medical decision", "None", "None"]', 1, 'Capacity is clinical and decision-specific. Competence is legal. (MGH Pocket)'),
    (v_topic_id, '8: What defines "Competence"?', '["A clinical diagnosis", "A global legal status determined by a judge", "The ability to speak English", "None"]', 1, 'Only a judge can declare someone legally incompetent. (Kaplan & Sadock)'),
    (v_topic_id, '9: A patient with Schizophrenia refuses a life-saving blood transfusion, stating, "My religion forbids it." He clearly understands the risks of death. Does he have capacity?', '["No, because he has Schizophrenia", "Yes, psychiatric illness does not automatically negate capacity, and religious beliefs are valid grounds for refusal if the patient understands the consequences", "None", "None"]', 1, 'Diagnosis does not equal lack of capacity. (First Aid)'),
    (v_topic_id, '10: A patient with Schizophrenia refuses a life-saving blood transfusion, stating, "The blood contains alien microchips that will steal my thoughts." Does he have capacity?', '["Yes", "No, his decision is based on a delusion rather than a rational understanding of the facts", "Only if his family agrees", "None"]', 1, 'He lacks the ability to appreciate the true nature of the medical situation due to psychosis. (MGH Pocket)'),
    (v_topic_id, '11: If a patient lacks capacity and has no advance directive or Medical Power of Attorney, who makes medical decisions for them?', '["The doctor", "Next of kin (usually spouse, then adult children, then parents, then siblings)", "The police", "None"]', 1, 'Surrogate decision-maker hierarchy. (Kaplan & Sadock)'),
    (v_topic_id, '12: What is "Informed Consent"?', '["Signing a paper", "A process where the physician explains the diagnosis, proposed treatment, risks, benefits, alternatives, and risks of no treatment, and the patient agrees", "None", "None"]', 1, 'It is a conversation, not just a signature. (First Aid)'),
    (v_topic_id, '13: In a true medical emergency where a patient is unconscious and bleeding to death, do you need informed consent to operate?', '["Yes, wake them up", "No, implied consent applies in life-threatening emergencies where a reasonable person would want treatment", "You must ask their neighbor", "None"]', 1, 'Implied consent doctrine. (MGH Pocket)'),
    (v_topic_id, '14: What is the most significant risk factor for completed suicide?', '["Being female", "A previous suicide attempt", "Being married", "Having children"]', 1, 'Past behavior is the best predictor of future behavior. (Kaplan & Sadock)'),
    (v_topic_id, '15: Which demographic has the highest rate of COMPLETED suicides in the United States?', '["Teenage girls", "Elderly white males", "Middle-aged women", "Children"]', 1, 'Often using highly lethal means (firearms). (First Aid)'),
    (v_topic_id, '16: Which gender attempts suicide more often?', '["Men", "Women (about 3 times more often than men)", "Equal", "None"]', 1, 'Women attempt more (often with pills), men complete more (often with firearms/hanging). (MGH Pocket)'),
    (v_topic_id, '17: What is the SAD PERSONS scale used for?', '["Assessing depression", "Assessing suicide risk factors", "Assessing alcohol withdrawal", "Assessing mania"]', 1, 'Sex, Age, Depression, Previous attempt, Ethanol use, Rational thinking loss, Social support lacking, Organized plan, No spouse, Sickness. (First Aid)'),
    (v_topic_id, '18: A patient is acutely suicidal, has a loaded gun at home, and a clear plan to shoot themselves tonight. What is the immediate next step?', '["Prescribe an SSRI and schedule a follow-up in 2 weeks", "Place the patient on an involuntary psychiatric hold and admit them to a secure psychiatric unit", "Call their spouse to take the gun", "None"]', 1, 'Imminent risk requires immediate inpatient stabilization. (Kaplan & Sadock)'),
    (v_topic_id, '19: Does asking a patient directly about suicidal thoughts increase their risk of committing suicide?', '["Yes, it puts the idea in their head", "No, asking directly is protective and essential for risk assessment", "Only in teenagers", "None"]', 1, 'A common myth. You MUST ask directly. (MGH Pocket)'),
    (v_topic_id, '20: What is a "No-Suicide Contract"?', '["A legally binding document", "A written or verbal agreement where the patient promises not to harm themselves. It has NO legal standing and is NOT a substitute for proper clinical assessment and safety planning.", "A cure", "None"]', 1, 'Do not rely on these for safety. Use a Safety Plan instead. (First Aid)'),
    (v_topic_id, '21: Which two psychiatric medications are specifically FDA-approved for reducing suicidality?', '["Fluoxetine and Haloperidol", "Lithium (for Bipolar) and Clozapine (for Schizophrenia)", "Sertraline and Valproate", "None"]', 1, 'These are unique among psychotropics for their anti-suicide properties. (Kaplan & Sadock)'),
    (v_topic_id, '22: A patient presents to the ER highly agitated, violent, and hallucinating. They require chemical restraint. What is the best initial IM medication option?', '["IV Diazepam", "IM Haloperidol or IM Olanzapine, often combined with a benzodiazepine (e.g., IM Lorazepam)", "IM Lithium", "None"]', 1, 'The "B52" (Haloperidol 5mg, Lorazepam 2mg) is a classic chemical restraint. (First Aid)'),
    (v_topic_id, '23: If a patient is chemically restrained with IM Olanzapine, which medication should NOT be given IM at the exact same time due to risk of severe bradycardia and respiratory depression?', '["Haloperidol", "IM Lorazepam (or other IM benzos)", "Diphenhydramine", "None"]', 1, 'A dangerous drug-drug interaction (IM Olanzapine + IM Benzo). Give them at least an hour apart. (MGH Pocket)'),
    (v_topic_id, '24: A patient in the ER is restrained with 4-point leather restraints due to severe violence. How often must they be clinically evaluated?', '["Every 24 hours", "Continuous direct observation (1:1), with frequent neurovascular checks and documented clinical reassessment (usually every 1-4 hours depending on age/hospital policy)", "Every shift", "None"]', 1, 'Physical restraints are a last resort and highly regulated. (Kaplan & Sadock)'),
    (v_topic_id, '25: What is "Neuroleptic Malignant Syndrome" (NMS)?', '["An allergy to SSRIs", "A life-threatening neurological emergency caused by dopamine antagonism (antipsychotics), characterized by fever, severe muscle rigidity (lead-pipe), autonomic instability, and altered mental status", "A type of seizure", "None"]', 1, 'A true medical emergency with high mortality. (First Aid)'),
    (v_topic_id, '26: Which laboratory findings are classically markedly elevated in NMS?', '["Troponin", "Creatine Kinase (CK/CPK) and White Blood Cell count (Leukocytosis)", "Amylase", "None"]', 1, 'Due to severe muscle breakdown (rhabdomyolysis) from the rigidity. (MGH Pocket)'),
    (v_topic_id, '27: What is the most important initial step in treating Neuroleptic Malignant Syndrome?', '["Give more antipsychotics", "Immediately DISCONTINUE the offending antipsychotic agent and provide aggressive supportive care (IV fluids, cooling blankets)", "Give antibiotics", "None"]', 1, 'Supportive care is paramount. (Kaplan & Sadock)'),
    (v_topic_id, '28: What pharmacological agents can be used to treat severe Neuroleptic Malignant Syndrome?', '["Haloperidol", "Dantrolene (a direct muscle relaxant) or Bromocriptine/Amantadine (dopamine agonists)", "Lithium", "None"]', 1, 'You need to relax the muscles and override the dopamine blockade. (First Aid)'),
    (v_topic_id, '29: What is "Serotonin Syndrome"?', '["Depression", "A life-threatening condition caused by excessive serotonergic activity, characterized by altered mental status, autonomic instability, and neuromuscular hyperactivity (e.g., hyperreflexia, clonus)", "Mania", "None"]', 1, 'Often caused by combining SSRIs with MAOIs, TCAs, or triptans. (MGH Pocket)'),
    (v_topic_id, '30: How do the physical exam findings of Serotonin Syndrome differ from NMS?', '["They are identical", "NMS has ''''lead-pipe'''' rigidity and hyporeflexia. Serotonin Syndrome has hyperreflexia, myoclonus, and ocular clonus.", "None", "None"]', 1, 'Reflexes are the key differentiating factor on the exam. (Kaplan & Sadock)'),
    (v_topic_id, '31: What is the antidote for severe Serotonin Syndrome?', '["Flumazenil", "Cyproheptadine (a 5-HT2 receptor antagonist)", "Naloxone", "None"]', 1, 'Blocks the serotonin receptors. (First Aid)'),
    (v_topic_id, '32: A patient presents with acute dystonia (e.g., torticollis, oculogyric crisis) shortly after receiving IM Haloperidol. What is the treatment?', '["More Haloperidol", "IM Benztropine or IM Diphenhydramine (anticholinergics)", "Epinephrine", "None"]', 1, 'Restores the dopamine-acetylcholine balance in the basal ganglia. (MGH Pocket)'),
    (v_topic_id, '33: What is a "Tardive Dyskinesia" emergency?', '["It is not an emergency", "It is usually a chronic, irreversible condition (lip smacking, choreoathetoid movements) caused by long-term antipsychotic use, but severe cases can impair breathing/swallowing", "None", "None"]', 1, 'Treat with VMAT2 inhibitors (Valbenazine) and stop the offending drug if possible. (Kaplan & Sadock)'),
    (v_topic_id, '34: A patient taking Lithium presents with coarse tremors, ataxia, vomiting, and confusion. What is the likely diagnosis?', '["Alcohol withdrawal", "Lithium Toxicity", "NMS", "None"]', 1, 'Lithium has a very narrow therapeutic index. (First Aid)'),
    (v_topic_id, '35: What is the treatment for severe Lithium toxicity (levels > 2.5 mEq/L with neurological symptoms or renal failure)?', '["Activated charcoal", "Hemodialysis", "IV Calcium", "None"]', 1, 'Lithium is a small ion that is easily dialyzable. (MGH Pocket)'),
    (v_topic_id, '36: A patient who ingested an unknown amount of Tricyclic Antidepressants (TCAs) presents with tachycardia, dilated pupils, and dry skin. What is the most dreaded complication?', '["Liver failure", "Fatal cardiac arrhythmias (widened QRS leading to Torsades/V-fib) and intractable seizures", "Kidney failure", "None"]', 1, 'TCAs block cardiac sodium channels. (Kaplan & Sadock)'),
    (v_topic_id, '37: What is the treatment for TCA cardiotoxicity (widened QRS complex)?', '["Amiodarone", "IV Sodium Bicarbonate", "Beta blockers", "None"]', 1, 'Bicarbonate overcomes the sodium channel blockade and alkalinizes the blood, reducing drug binding. (First Aid)'),
    (v_topic_id, '38: A patient taking Tranylcypromine (an MAOI) presents with a severe headache, flushing, and a blood pressure of 220/120 after eating aged cheese and drinking red wine. Diagnosis?', '["Migraine", "Hypertensive Crisis (Tyramine reaction)", "Stroke", "None"]', 1, 'Tyramine acts as a sympathomimetic when MAO is blocked. (MGH Pocket)'),
    (v_topic_id, '39: What is the treatment for an MAOI-induced hypertensive crisis?', '["Beta blockers only", "Phentolamine (alpha-1 antagonist) or Nitroprusside", "Epinephrine", "None"]', 1, 'You must block the massive alpha-adrenergic vasoconstriction. (Kaplan & Sadock)'),
    (v_topic_id, '40: A patient presents to the ER with pinpoint pupils, respiratory depression (RR 6), and unresponsiveness. Diagnosis and Treatment?', '["Benzodiazepine overdose; give Flumazenil", "Opioid overdose; give Naloxone (Narcan) immediately", "Alcohol poisoning; give Thiamine", "None"]', 1, 'Naloxone is a competitive opioid receptor antagonist. (First Aid)'),
    (v_topic_id, '41: A chronic alcoholic is brought to the ER confused, with ataxia and nystagmus (ophthalmoplegia). What is the diagnosis?', '["Delirium Tremens", "Wernicke''s Encephalopathy", "Stroke", "None"]', 1, 'The classic triad of Wernicke''s. (MGH Pocket)'),
    (v_topic_id, '42: What must be administered IMMEDIATELY to a patient with suspected Wernicke''s Encephalopathy?', '["IV Glucose", "IV Thiamine (Vitamin B1) BEFORE or WITH glucose", "IV Haloperidol", "None"]', 1, 'Giving glucose without thiamine will precipitate or worsen the encephalopathy. (Kaplan & Sadock)'),
    (v_topic_id, '43: If Wernicke''s Encephalopathy is not treated promptly, what irreversible condition can develop?', '["Dementia", "Korsakoff''s Syndrome (anterograde/retrograde amnesia and confabulation)", "Schizophrenia", "None"]', 1, 'Damage to the mammillary bodies. (First Aid)'),
    (v_topic_id, '44: A patient who stopped drinking alcohol 3 days ago presents with severe agitation, visual hallucinations of bugs crawling on the wall, tachycardia, sweating, and a fever. Diagnosis?', '["Schizophrenia", "Delirium Tremens (severe alcohol withdrawal)", "Heroin withdrawal", "None"]', 1, 'A medical emergency with a high mortality rate if untreated. (MGH Pocket)'),
    (v_topic_id, '45: What is the gold standard treatment for Delirium Tremens?', '["Antipsychotics", "High-dose Benzodiazepines (e.g., IV Diazepam, Lorazepam, or Chlordiazepoxide) titrated to symptoms", "Beta blockers", "None"]', 1, 'Benzos substitute for the missing alcohol at the GABA receptor. (Kaplan & Sadock)'),
    (v_topic_id, '46: In a patient with severe liver disease (cirrhosis) experiencing alcohol withdrawal, which benzodiazepines are preferred?', '["Diazepam and Chlordiazepoxide", "Lorazepam, Oxazepam, or Temazepam (the ''''LOT'''' benzos)", "Alprazolam", "None"]', 1, 'They are metabolized solely by glucuronidation and do not have active metabolites that accumulate in liver failure. (First Aid)'),
    (v_topic_id, '47: A patient intentionally overdosed on Acetaminophen (Tylenol) 4 hours ago. What is the antidote?', '["Naloxone", "N-acetylcysteine (NAC)", "Flumazenil", "None"]', 1, 'Replenishes glutathione to detoxify the toxic NAPQI metabolite. (MGH Pocket)'),
    (v_topic_id, '48: A patient is found unconscious with empty pill bottles. They have profound respiratory depression, but pupils are NORMAL size. What did they likely overdose on?', '["Heroin", "Benzodiazepines or Barbiturates", "Cocaine", "None"]', 1, 'Opioids cause pinpoint pupils; sedative-hypnotics usually do not. (Kaplan & Sadock)'),
    (v_topic_id, '49: Why is Flumazenil rarely used for suspected Benzodiazepine overdose in the ER?', '["It doesn''t work", "It can precipitate intractable, life-threatening seizures, especially in chronic benzo users or mixed overdoses (e.g., with TCAs)", "It causes respiratory depression", "None"]', 1, 'Supportive care (intubation if needed) is generally safer. (First Aid)'),
    (v_topic_id, '50: A patient presents with extreme agitation, paranoia, dilated pupils, tachycardia, hypertension, and formication (feeling bugs crawling under the skin). What substance did they likely use?', '["Heroin", "Cocaine or Methamphetamine (severe stimulant intoxication)", "Marijuana", "None"]', 1, 'Meth "mites" and cocaine "bugs" are classic tactile hallucinations. (MGH Pocket)'),
    (v_topic_id, '51: What medication should NEVER be given as monotherapy to a patient with severe cocaine toxicity (hypertension/tachycardia)?', '["Benzodiazepines", "Pure Beta-blockers (e.g., Propranolol)", "Alpha blockers", "None"]', 1, 'Causes unopposed alpha-adrenergic stimulation, leading to catastrophic hypertension and coronary vasospasm. (Kaplan & Sadock)'),
    (v_topic_id, '52: What is the best initial treatment for stimulant-induced agitation and cardiovascular toxicity?', '["Haloperidol", "Benzodiazepines (e.g., Lorazepam)", "Beta blockers", "None"]', 1, 'Benzos calm the CNS and reduce the sympathetic outflow. (First Aid)'),
    (v_topic_id, '53: A patient is brought to the ER highly combative, with vertical and horizontal nystagmus, decreased pain perception, and immense physical strength. What drug did they take?', '["Cocaine", "Phencyclidine (PCP)", "LSD", "None"]', 1, 'Nystagmus (especially rotary or vertical) is the hallmark physical exam finding for PCP. (MGH Pocket)'),
    (v_topic_id, '54: A young adult presents to the ER anxious, feeling like they are having a heart attack, with a fast heart rate. They report smoking something an hour ago. Conjunctival injection (red eyes) is present. Diagnosis?', '["Cocaine intoxication", "Cannabis (Marijuana) induced panic attack", "Opioid withdrawal", "None"]', 1, 'Red eyes and increased appetite are classic for cannabis; panic attacks are a common adverse effect, especially in naive users. (Kaplan & Sadock)'),
    (v_topic_id, '55: A patient presents with tearing (lacrimation), yawning, rhinorrhea, piloerection (goosebumps), muscle aches, and diarrhea. Diagnosis?', '["Flu", "Opioid withdrawal", "Alcohol withdrawal", "None"]', 1, 'Highly uncomfortable ("cold turkey") but rarely life-threatening, unlike alcohol withdrawal. (First Aid)'),
    (v_topic_id, '56: What medication can be used to treat the autonomic symptoms (tachycardia, sweating) of opioid withdrawal?', '["Naloxone", "Clonidine (an alpha-2 agonist)", "Fluoxetine", "None"]', 1, 'It blunts the sympathetic overdrive. (MGH Pocket)'),
    (v_topic_id, '57: A patient who has been vomiting for days presents with severe lethargy. Sodium is found to be 110 mEq/L. The resident rapidly corrects the sodium to 135 mEq/L over 12 hours. What is the dreaded complication?', '["Heart failure", "Osmotic Demyelination Syndrome (Central Pontine Myelinolysis)", "Stroke", "None"]', 1, 'Correcting sodium too fast causes fluid to rush out of brain cells, destroying myelin in the pons. (Kaplan & Sadock)'),
    (v_topic_id, '58: A patient with Schizophrenia drinks massive amounts of water daily (primary polydipsia). They present with seizures and confusion. What is the electrolyte abnormality?', '["Hypernatremia", "Severe Hyponatremia (water intoxication)", "Hyperkalemia", "None"]', 1, 'A known complication in chronic schizophrenia. (First Aid)'),
    (v_topic_id, '59: What is "Factitious Disorder Imposed on Another" (Munchausen by proxy)?', '["Faking illness for money", "A caregiver intentionally producing or feigning illness in a dependent (usually a child) to assume the sick role by proxy", "A delusion", "None"]', 1, 'This is a severe form of child abuse and a psychiatric emergency requiring CPS involvement. (MGH Pocket)'),
    (v_topic_id, '60: A doctor suspects a child is being physically abused by their parents. Does the doctor need absolute proof before reporting to Child Protective Services?', '["Yes", "No, reasonable suspicion is sufficient and legally mandated for all healthcare providers", "Only if the child admits it", "None"]', 1, 'Failure to report is a crime and a breach of ethics. (Kaplan & Sadock)'),
    (v_topic_id, '61: What is the M''Naghten Rule?', '["A rule for prescribing meds", "A legal standard for the insanity defense; the defendant did not know the nature/quality of the act, or did not know that the act was wrong, due to a mental disease", "A civil commitment rule", "None"]', 1, 'The "right-wrong" test for criminal responsibility. (First Aid)'),
    (v_topic_id, '62: What is the "Durham Rule"?', '["A rule for informed consent", "A legal standard for the insanity defense; the criminal act was the ''''product'''' of a mental disease or defect", "A Tarasoff rule", "None"]', 1, 'Broad standard, mostly replaced now. (MGH Pocket)'),
    (v_topic_id, '63: What does it mean if a defendant is found "Incompetent to Stand Trial"?', '["They are innocent", "Due to mental illness, they cannot currently understand the charges against them or assist their attorney in their defense", "They have amnesia", "None"]', 1, 'This addresses their mental state AT THE TIME OF THE TRIAL, not at the time of the crime. (Kaplan & Sadock)'),
    (v_topic_id, '64: Does the insanity defense evaluate the patient''s mental state at the time of the trial, or at the time of the crime?', '["At the time of the trial", "At the TIME OF THE CRIME", "Both", "Neither"]', 1, 'Insanity = past mental state. Competence = present mental state. (First Aid)'),
    (v_topic_id, '65: What is "Malpractice"?', '["Making a mistake", "A tort (civil wrong) requiring 4 elements: Duty, Dereliction (Breach of duty), Damages, and Direct causation (Proximate cause)", "Breaking confidentiality", "None"]', 1, 'The "4 Ds" of malpractice. (MGH Pocket)'),
    (v_topic_id, '66: A physician prescribes a lethal dose of a medication intentionally to help a terminally ill patient die. What is this called?', '["Euthanasia", "Physician-Assisted Suicide (legal in a few states, but ethically highly debated)", "Malpractice", "None"]', 1, 'In PAS, the patient self-administers the lethal dose. In active euthanasia, the doctor administers it. (Kaplan & Sadock)'),
    (v_topic_id, '67: What is a "Psychiatric Advance Directive"?', '["A will", "A legal document where a competent patient specifies their preferences for psychiatric treatment (e.g., which meds they refuse) in case they lose capacity in the future", "A prescription", "None"]', 1, 'Highly useful for patients with severe Bipolar Disorder or Schizophrenia. (First Aid)'),
    (v_topic_id, '68: Can a patient be forced to take psychiatric medication against their will in a non-emergency outpatient setting?', '["Yes, always", "Generally no, unless they are under a specific court order (e.g., Assisted Outpatient Treatment) declaring them incompetent to refuse", "Only if the family agrees", "None"]', 1, 'Medication over objection requires a rigorous legal process. (MGH Pocket)'),
    (v_topic_id, '69: A patient in the ER is trying to punch a nurse right now. Can they be given IM Haloperidol against their will?', '["No, you must wait for a judge", "Yes, in acute emergencies where there is imminent physical danger to the patient or staff, emergency chemical restraint is legally and ethically permitted", "Only if family consents", "None"]', 1, 'Safety first. (Kaplan & Sadock)'),
    (v_topic_id, '70: A patient with severe anorexia nervosa (BMI 11) is actively refusing food and IV fluids, stating she wants to die. She is medically unstable. What is the appropriate action?', '["Respect her autonomy and provide comfort care", "Institute involuntary life-saving treatment (feeding tube/IV fluids); extreme malnutrition impairs capacity, and this is a life-threatening psychiatric emergency", "Call her parents", "None"]', 1, 'Anorexia nervosa can profoundly impair a patient''s capacity to make safe decisions. (First Aid)'),
    (v_topic_id, '71: What is "Habeas Corpus" in the context of psychiatry?', '["A type of therapy", "The legal right of an involuntarily committed patient to petition a court to review the legality of their confinement", "A side effect", "None"]', 1, 'Protects against unlawful psychiatric imprisonment. (MGH Pocket)'),
    (v_topic_id, '72: A patient asks to read their own psychiatric chart. Do they have the right to do so?', '["No, never", "Yes, under HIPAA patients generally have the right to access their medical records, though psychotherapy notes are often protected/exempt", "Only with a lawyer", "None"]', 1, 'Patients own the information in their chart. (Kaplan & Sadock)'),
    (v_topic_id, '73: A doctor is subpoenaed to testify about a patient in a divorce case. The patient has NOT given consent for the doctor to speak. What should the doctor do?', '["Answer all questions", "Assert physician-patient privilege and refuse to release records or testify unless ordered by a judge", "Call the police", "None"]', 1, 'A subpoena is just a request for information; a judge''s order compels it. (First Aid)'),
    (v_topic_id, '74: What is "Parens Patriae"?', '["A type of delusion", "The legal doctrine granting the state the authority to protect those who are unable to protect themselves (used to justify involuntary commitment of the gravely disabled)", "A malpractice term", "None"]', 1, 'The state acting as a "parent." (MGH Pocket)'),
    (v_topic_id, '75: What is the "Police Power" of the state in psychiatry?', '["The right to arrest doctors", "The authority of the state to protect society from harm (used to justify involuntary commitment of patients who are a danger to others)", "None", "None"]', 1, 'The other legal justification for involuntary holds. (Kaplan & Sadock)'),
    (v_topic_id, '76: A patient presents with acute delirium. What is the most critical first step?', '["Prescribe Haloperidol", "Perform a thorough medical workup (labs, imaging, tox screen) to identify and treat the underlying medical cause", "Send to psychiatry", "None"]', 1, 'Delirium is a medical emergency, not a primary psychiatric disease. (First Aid)'),
    (v_topic_id, '77: Which class of medications is notorious for causing delirium in the elderly?', '["SSRIs", "Anticholinergics (e.g., Diphenhydramine, TCAs, Oxybutynin)", "Penicillin", "None"]', 1, '"Blind as a bat, mad as a hatter..." (MGH Pocket)'),
    (v_topic_id, '78: A patient on an SSRI takes a massive dose of St. John''s Wort. They present with tremor, hyperreflexia, and confusion. What is the diagnosis?', '["NMS", "Serotonin Syndrome", "Lithium Toxicity", "None"]', 1, 'St. John''s Wort is a potent serotonergic herbal supplement. (Kaplan & Sadock)'),
    (v_topic_id, '79: A patient with known Schizophrenia stops taking their clozapine for 5 days. Why must the medication be re-titrated slowly rather than restarting at the full dose?', '["To avoid liver failure", "To avoid profound orthostatic hypotension, seizures, and cardiovascular collapse", "It doesn''t need to be", "None"]', 1, 'Clozapine has a very specific titration schedule if missed for > 48 hours. (First Aid)'),
    (v_topic_id, '80: A patient taking Clozapine presents to the ER with a fever and sore throat. What is the immediate required test?', '["Chest X-ray", "Complete Blood Count (CBC) to check for severe neutropenia/agranulocytosis", "ECG", "None"]', 1, 'Agranulocytosis is a fatal complication of Clozapine. (MGH Pocket)'),
    (v_topic_id, '81: A patient taking Lamotrigine presents with a spreading, blistering rash that involves the mucous membranes of the mouth and eyes. Diagnosis?', '["Acne", "Stevens-Johnson Syndrome (SJS) or Toxic Epidermal Necrolysis (TEN)", "Psoriasis", "None"]', 1, 'A dermatological emergency requiring burn unit care. (Kaplan & Sadock)'),
    (v_topic_id, '82: What is the most common cause of Lamotrigine-induced SJS?', '["Taking it with food", "Rapid dose titration; the dose must be increased very slowly over weeks to minimize this risk", "Taking it in the morning", "None"]', 1, 'Never start Lamotrigine at a high dose. (First Aid)'),
    (v_topic_id, '83: A patient taking Valproic Acid (Depakote) presents with severe abdominal pain radiating to the back, nausea, and vomiting. What complication should be suspected?', '["Appendicitis", "Acute Pancreatitis or Hepatotoxicity", "Gallstones", "None"]', 1, 'Check amylase, lipase, and LFTs immediately. (MGH Pocket)'),
    (v_topic_id, '84: A patient taking Carbamazepine develops easy bruising, fatigue, and frequent infections. What is the suspected complication?', '["Aplastic Anemia or Agranulocytosis", "Liver failure", "Kidney failure", "None"]', 1, 'Carbamazepine suppresses the bone marrow. (Kaplan & Sadock)'),
    (v_topic_id, '85: A young man with Schizophrenia develops a sustained, painful upward gaze of his eyes (oculogyric crisis) after starting Haloperidol. This is a form of:', '["Tardive Dyskinesia", "Acute Dystonia", "Akathisia", "None"]', 1, 'A terrifying but easily treatable extrapyramidal symptom (EPS). (First Aid)'),
    (v_topic_id, '86: A patient on Risperidone presents with intense, unbearable inner restlessness. They are constantly pacing the room and cannot sit still. Diagnosis?', '["Mania", "Akathisia", "Parkinsonism", "None"]', 1, 'Often mistaken for worsening agitation or psychosis. (MGH Pocket)'),
    (v_topic_id, '87: What is the best pharmacological treatment for Akathisia?', '["More Risperidone", "Propranolol (Beta-blocker) or Benztropine, or lowering the antipsychotic dose", "Lithium", "None"]', 1, 'Beta-blockers are first-line. (Kaplan & Sadock)'),
    (v_topic_id, '88: A patient on Fluphenazine develops a slow, shuffling gait, cogwheel rigidity, and a resting tremor. Diagnosis?', '["Huntington''s disease", "Pseudoparkinsonism (Antipsychotic-induced Parkinsonism)", "Akathisia", "None"]', 1, 'Due to dopamine blockade in the nigrostriatal pathway. (First Aid)'),
    (v_topic_id, '89: A patient who has been on Haloperidol for 10 years constantly smacks their lips and protrudes their tongue. Diagnosis?', '["Acute dystonia", "Tardive Dyskinesia (TD)", "Tourette''s", "None"]', 1, 'Often irreversible. Caused by dopamine receptor upregulation/supersensitivity. (MGH Pocket)'),
    (v_topic_id, '90: Which antipsychotic is famously LEAST likely to cause Tardive Dyskinesia and is often the treatment of choice for patients who develop severe TD?', '["Haloperidol", "Clozapine", "Risperidone", "None"]', 1, 'Clozapine has almost zero risk of EPS/TD. (Kaplan & Sadock)'),
    (v_topic_id, '91: A patient is brought to the ER with priapism (a painful, prolonged erection lasting > 4 hours). Which psychiatric medication is the classic culprit?', '["Fluoxetine", "Trazodone", "Lithium", "None"]', 1, '"Trazobone." A urologic emergency requiring intracavernosal phenylephrine or aspiration. (First Aid)'),
    (v_topic_id, '92: A 75-year-old patient with dementia is highly agitated in the nursing home. The doctor orders IM Haloperidol. What "Black Box Warning" applies here?', '["Risk of seizures", "Increased risk of death in elderly patients with dementia-related psychosis treated with antipsychotics", "Risk of bleeding", "None"]', 1, 'Usually due to cardiovascular events or pneumonia. (MGH Pocket)'),
    (v_topic_id, '93: A pregnant woman with Bipolar Disorder takes Lithium during her first trimester. What specific congenital heart defect is the fetus at risk for?', '["Tetralogy of Fallot", "Ebstein''s Anomaly (downward displacement of the tricuspid valve)", "VSD", "None"]', 1, 'A classic board exam pearl. (Kaplan & Sadock)'),
    (v_topic_id, '94: A pregnant woman takes Valproic Acid during her first trimester. What specific congenital defect is the fetus at risk for?', '["Heart defects", "Neural Tube Defects (e.g., Spina Bifida)", "Cleft lip", "None"]', 1, 'Valproate profoundly depletes folate. (First Aid)'),
    (v_topic_id, '95: A patient with Major Depressive Disorder decides to stop taking their Paroxetine abruptly. Two days later, they experience "brain zaps," flu-like symptoms, dizziness, and crying spells. Diagnosis?', '["Serotonin Syndrome", "SSRI Discontinuation Syndrome", "NMS", "None"]', 1, 'Paroxetine and Venlafaxine have very short half-lives and are notorious for this. Reassure and taper slowly. (MGH Pocket)'),
    (v_topic_id, '96: Which SSRI has the longest half-life and is therefore LEAST likely to cause Discontinuation Syndrome?', '["Paroxetine", "Fluoxetine", "Sertraline", "None"]', 1, 'Fluoxetine essentially auto-tapers itself over weeks. (Kaplan & Sadock)'),
    (v_topic_id, '97: A patient ingests antifreeze (ethylene glycol) in a suicide attempt. What is the specific antidote?', '["Naloxone", "Fomepizole (or Ethanol) to competitively inhibit alcohol dehydrogenase", "Flumazenil", "None"]', 1, 'Prevents the conversion of ethylene glycol into toxic metabolites (oxalic acid). (First Aid)'),
    (v_topic_id, '98: A patient is acutely manic, jumping on tables in the ER and destroying equipment. They refuse oral medication. What is the fastest acting IM option?', '["IM Lithium", "IM Olanzapine or IM Haloperidol", "IM Fluoxetine", "None"]', 1, 'Lithium is only available orally and takes days to work. Antipsychotics work in minutes. (MGH Pocket)'),
    (v_topic_id, '99: A patient presents with acute catatonia (mutism, posturing, waxy flexibility) and has stopped eating and drinking. What is the treatment of choice to rapidly reverse the catatonia?', '["Haloperidol", "High-dose Benzodiazepines (e.g., Lorazepam challenge) or Electroconvulsive Therapy (ECT)", "Lithium", "None"]', 1, 'Antipsychotics can worsen catatonia or precipitate NMS. (Kaplan & Sadock)'),
    (v_topic_id, '100: A patient with severe, treatment-resistant depression is actively suicidal and refusing to eat. What is the most rapid, effective, and life-saving intervention available?', '["Increase their SSRI", "Electroconvulsive Therapy (ECT)", "Psychoanalysis", "None"]', 1, 'ECT is the gold standard for rapid response in severe depression with life-threatening features. (First Aid)'),
    (v_topic_id, '101: What is the absolute contraindication for ECT?', '["Pregnancy", "There are NO absolute contraindications to ECT, though space-occupying brain lesions and recent MI increase the risk", "Old age", "None"]', 1, 'ECT is even safe in all trimesters of pregnancy. (MGH Pocket)'),
    (v_topic_id, '102: What is the most common side effect of ECT?', '["Seizures", "Transient anterograde and retrograde amnesia (memory loss), which usually resolves within weeks/months", "Death", "None"]', 1, 'Bilateral ECT has a higher risk of memory loss than unilateral. (Kaplan & Sadock)'),
    (v_topic_id, '103: A patient is acutely intoxicated with PCP. They are highly violent. How should they be managed?', '["Talk them down", "Minimize sensory stimulation (dark, quiet room) to prevent triggering further violence, and use Benzodiazepines for chemical restraint", "Give Haloperidol immediately", "None"]', 1, 'Sensory overload makes PCP intoxication much worse. (First Aid)'),
    (v_topic_id, '104: A patient presents to the ER with extreme hyperthermia (106 F), severe muscle rigidity, and dark urine. They recently started taking Fluphenazine. Diagnosis?', '["Serotonin Syndrome", "Neuroleptic Malignant Syndrome (NMS) with Rhabdomyolysis", "Heat stroke", "None"]', 1, 'Dark urine indicates myoglobinuria from muscle breakdown, leading to renal failure. (MGH Pocket)'),
    (v_topic_id, '105: How does the rigidity in NMS differ from normal muscle tension?', '["It is mild", "It is described as ''''lead-pipe'''' rigidity, meaning the resistance is sustained throughout the entire range of passive movement", "It only affects the legs", "None"]', 1, 'Unlike cogwheel rigidity, which has a ratchet-like catch. (Kaplan & Sadock)'),
    (v_topic_id, '106: A patient presents to the ER highly combative and confused. They are shivering, sweating profusely, and their pupils are dilated. Reflexes are 4+ with sustained ankle clonus. They take Sertraline and recently took an OTC cough medicine. What did the OTC medicine likely contain?', '["Acetaminophen", "Dextromethorphan (a potent serotonin reuptake inhibitor), triggering Serotonin Syndrome", "Guaifenesin", "None"]', 1, 'A classic drug-drug interaction. (First Aid)'),
    (v_topic_id, '107: A 22-year-old college student dies suddenly at a rave after having a seizure and a temperature of 107 F. What recreational drug did they most likely take?', '["Marijuana", "MDMA (Ecstasy/Molly)", "Heroin", "None"]', 1, 'MDMA is an amphetamine derivative that causes massive serotonin release, mimicking Serotonin Syndrome. (MGH Pocket)'),
    (v_topic_id, '108: What is "Bath Salts"?', '["A soap", "Synthetic cathinones (amphetamine-like stimulants) that cause extreme agitation, paranoia, hallucinations, and violent behavior", "Opioids", "None"]', 1, 'Often not detected on standard urine drug screens. (Kaplan & Sadock)'),
    (v_topic_id, '109: A patient is admitted to the hospital for elective surgery. On hospital day 3, they become acutely agitated, tachycardic, and start picking invisible bugs off their skin. What is the most important historical question to ask their family?', '["Do they have schizophrenia?", "How much alcohol do they drink daily? (Suspect Delirium Tremens)", "Do they have dementia?", "None"]', 1, 'DTs peak 48-96 hours after the last drink. (First Aid)'),
    (v_topic_id, '110: A patient presents with acute opioid overdose. You give IV Naloxone, and they wake up immediately. They want to leave the ER against medical advice. Why must you strongly advise them to stay?', '["They need a psych consult", "Naloxone''s half-life (30-60 minutes) is much SHORTER than the half-life of most opioids (e.g., methadone); they will re-overdose when the Naloxone wears off", "They are arrested", "None"]', 1, 'A fatal trap if the patient walks out. (MGH Pocket)'),
    (v_topic_id, '111: A patient intentionally ingests 50 tablets of Aspirin (Salicylates). What is the classic initial acid-base disturbance?', '["Respiratory acidosis", "Primary respiratory alkalosis (due to direct stimulation of the medullary respiratory center)", "Metabolic alkalosis", "None"]', 1, 'Later, it transitions to a mixed metabolic acidosis. (Kaplan & Sadock)'),
    (v_topic_id, '112: What is the treatment for Aspirin (Salicylate) overdose?', '["N-acetylcysteine", "Alkalinization of the urine with IV Sodium Bicarbonate (to promote excretion) and possibly hemodialysis", "Flumazenil", "None"]', 1, 'Salicylates are weak acids; alkalinizing the urine traps the ion, preventing reabsorption. (First Aid)'),
    (v_topic_id, '113: A patient with Bipolar Disorder takes Lithium and Ibuprofen (an NSAID) together. What happens?', '["Nothing", "NSAIDs decrease renal clearance of Lithium, rapidly causing Lithium toxicity", "Lithium stops working", "None"]', 1, 'A highly tested drug interaction. (MGH Pocket)'),
    (v_topic_id, '114: Which medication can safely be used for pain in a patient taking Lithium?', '["Ibuprofen", "Acetaminophen (Tylenol) or Sulindac", "Naproxen", "None"]', 1, 'Acetaminophen does not affect renal clearance of Lithium. (Kaplan & Sadock)'),
    (v_topic_id, '115: A patient with Schizophrenia becomes catatonic. You try a Lorazepam challenge (giving 1-2 mg IV Lorazepam). The patient dramatically wakes up and starts talking normally 10 minutes later. What does this confirm?', '["They were faking", "The diagnosis of Catatonia (which is highly responsive to Benzodiazepines)", "They have an infection", "None"]', 1, 'A positive Lorazepam challenge is diagnostic and therapeutic. (First Aid)'),
    (v_topic_id, '116: If a catatonic patient does NOT respond to high-dose Benzodiazepines, what is the next step?', '["Haloperidol", "Electroconvulsive Therapy (ECT)", "Psychoanalysis", "None"]', 1, 'ECT is life-saving for malignant catatonia. (MGH Pocket)'),
    (v_topic_id, '117: What is the difference between "Malignant Catatonia" and "Neuroleptic Malignant Syndrome"?', '["They are the same", "They are clinically almost indistinguishable (fever, rigidity, autonomic instability), but NMS is triggered by an antipsychotic, whereas Malignant Catatonia is the end-stage of untreated psychiatric catatonia", "None", "None"]', 1, 'Both are medical emergencies. (Kaplan & Sadock)'),
    (v_topic_id, '118: A patient is court-ordered to receive monthly IM injections of Haloperidol Decanoate because they frequently stop their oral meds, become violently psychotic, and get arrested. What is this legal mechanism called?",', '["Tarasoff", "Assisted Outpatient Treatment (AOT) / Kendra''s Law", "Malpractice", "None"]', 1, 'A civil court order requiring a patient to comply with treatment in the community. (First Aid)'),
    (v_topic_id, '119: A 14-year-old boy is brought to the ER by police for shooting at cars. He refuses to speak. His parents refuse psychiatric admission, stating "he is just being a boy," and demand to take him home. What must the ER doctor do?",', '["Let them go", "Hold the child involuntarily and notify Child Protective Services; parents cannot refuse life-saving psychiatric/medical care if the child is an imminent danger to himself/others", "Give him a toy", "None"]', 1, 'The state steps in (Parens Patriae) when parents fail to protect. (MGH Pocket)'),
    (v_topic_id, '120: A patient with dementia is driving and repeatedly gets into accidents. The psychiatrist tells the patient to stop driving, but the patient refuses. Does the psychiatrist have a duty to report this?",', '["No", "Yes, in many states physicians have a legal duty to report medically impaired drivers to the Department of Motor Vehicles (DMV)", "Only if the patient kills someone", "None"]', 1, 'Similar to Tarasoff (duty to protect the public). (Kaplan & Sadock)'),
    (v_topic_id, '121: A 25-year-old patient with Schizophrenia lives with their elderly mother. The patient steals her Social Security checks and frequently pushes her down the stairs. What is the doctor''s legal obligation?",', '["None", "Mandatory reporting to Adult Protective Services (APS) for Elder Abuse", "Call the patient''s father", "None"]', 1, 'Elder abuse (physical, financial, emotional) must be reported. (First Aid)'),
    (v_topic_id, '122: What constitutes "Emancipation" for a minor, allowing them to make all their own medical decisions?",', '["Turning 16", "Being legally married, being in the active military, or having a court declaration of emancipation", "Having a job", "None"]', 1, 'Varies by state, but these are the classic criteria. (MGH Pocket)'),
    (v_topic_id, '123: A 17-year-old girl who is NOT emancipated comes to the ER requesting treatment for Gonorrhea. Does she need parental consent?",', '["Yes", "No, all 50 states allow minors to consent to diagnosis and treatment of sexually transmitted diseases without parental knowledge", "Only if she is pregnant", "None"]', 1, 'Public health exception to encourage treatment. (Kaplan & Sadock)'),
    (v_topic_id, '124: Can a non-emancipated minor consent to inpatient psychiatric admission without their parents?",', '["Yes", "No, parental consent is required for inpatient psychiatric admission of a non-emancipated minor (unless it is an emergency involuntary hold)", "None", "None"]', 1, 'Parents control psychiatric and surgical care, outside of emergencies. (First Aid)'),
    (v_topic_id, '125: A patient calls their psychiatrist and says, "I just swallowed a whole bottle of Tylenol, goodbye." What is the FIRST thing the psychiatrist should do?",', '["Hang up and call 911", "Keep the patient on the phone, establish their location, and have someone else call 911 immediately", "Tell them to drink milk", "None"]', 1, 'Maintain contact while dispatching emergency services. (MGH Pocket)'),
    (v_topic_id, '126: A patient in the ER demands to leave. They have severe depression but deny suicidal ideation. They have a history of 3 previous suicide attempts. They are calm. Can you hold them involuntarily?",', '["Yes, past attempts guarantee future attempts", "No, if they do not meet CURRENT criteria for imminent danger to self/others or grave disability, you cannot legally hold them, despite the high historical risk", "None", "None"]', 1, 'Involuntary commitment requires IMMINENT risk. (Kaplan & Sadock)'),
    (v_topic_id, '127: What is "Grave Disability" in the context of involuntary commitment?",', '["Being in a wheelchair", "A condition where a person, as a result of a mental disorder, is unable to provide for their basic personal needs for food, clothing, or shelter", "Being homeless", "None"]', 1, 'Homelessness alone is not grave disability; it must be DUE to the mental illness. (First Aid)'),
    (v_topic_id, '128: A patient is brought to the ER with pinpoint pupils and respiratory depression. You suspect opioid overdose, but Naloxone has NO effect. What other drug class could cause this presentation?",', '["Cocaine", "Clonidine (an alpha-2 agonist) overdose can perfectly mimic opioid overdose (pinpoint pupils, bradycardia, hypotension, lethargy)", "Amphetamines", "None"]', 1, 'Clonidine toxicity is a classic mimic. (MGH Pocket)'),
    (v_topic_id, '129: A patient who ingested an unknown substance presents with severe agitation, hyperthermia, flushed (red) skin, dry mouth, dilated pupils, and absent bowel sounds. Diagnosis?",', '["Opioid overdose", "Anticholinergic Toxicity (e.g., Diphenhydramine, Atropine, TCAs, Jimson weed)", "Cholinergic toxicity", "None"]', 1, 'Hot as a hare, red as a beet, dry as a bone, blind as a bat, mad as a hatter, full as a flask. (Kaplan & Sadock)'),
    (v_topic_id, '130: What is the specific antidote for severe, life-threatening Anticholinergic Toxicity?",', '["Atropine", "Physostigmine (an acetylcholinesterase inhibitor that crosses the blood-brain barrier)", "Naloxone", "None"]', 1, 'Increases acetylcholine to overcome the blockade. (First Aid)'),
    (v_topic_id, '131: A farmer is brought to the ER sweating profusely, salivating, vomiting, with severe diarrhea, muscle fasciculations, and pinpoint pupils. He was spraying crops. Diagnosis?",', '["Anticholinergic toxicity", "Organophosphate Poisoning (Cholinergic Toxicity from acetylcholinesterase inhibition)", "Opioid overdose", "None"]', 1, 'DUMBELS: Diarrhea, Urination, Miosis, Bronchospasm, Emesis, Lacrimation, Salivation. (MGH Pocket)'),
    (v_topic_id, '132: What are the two antidotes for Organophosphate Poisoning?",', '["Physostigmine", "Atropine (to block muscarinic receptors) AND Pralidoxime/2-PAM (to regenerate the acetylcholinesterase enzyme at nicotinic receptors)", "Naloxone", "None"]', 1, 'Must give Atropine first to clear the airway secretions. (Kaplan & Sadock)'),
    (v_topic_id, '133: A patient who is a known IV drug user presents with a high fever, a new heart murmur, and Roth spots. Diagnosis?",', '["Pneumonia", "Infective Endocarditis (often Staph aureus affecting the Tricuspid valve)", "Hepatitis C", "None"]', 1, 'A medical emergency heavily associated with psychiatric/substance use populations. (First Aid)'),
    (v_topic_id, '134: A patient with Schizophrenia has been drinking 10 liters of water a day. Their serum sodium is 112 mEq/L. They are having a seizure. What is the treatment?",', '["Water restriction only", "Immediate administration of Hypertonic Saline (3% NaCl) to stop the seizure, being careful not to correct too rapidly overall", "Normal saline", "None"]', 1, 'Seizures dictate aggressive but careful intervention. (MGH Pocket)'),
    (v_topic_id, '135: What psychiatric medication is most likely to cause Hyponatremia (SIADH)?",', '["Lithium", "SSRIs (especially in the elderly) and Carbamazepine", "Haloperidol", "None"]', 1, 'Always check sodium if an elderly patient on an SSRI becomes confused. (Kaplan & Sadock)'),
    (v_topic_id, '136: A patient is brought to the ER by police. The patient is calm, cooperative, and states, "I know I have bipolar disorder, and I am currently manic. I need to be admitted." Does this require an involuntary hold?",', '["Yes, because police brought him", "No, if the patient has capacity and agrees to Voluntarily sign into the hospital, you do not need an involuntary hold", "Yes", "None"]', 1, 'Voluntary admission is always preferred if the patient is willing and capable. (First Aid)'),
    (v_topic_id, '137: A patient voluntarily admits themselves to the psychiatric unit. The next day, they demand to leave. Can they leave immediately?",', '["Yes, immediately", "No, voluntary patients must give notice (e.g., 72 hours written notice) allowing the psychiatrist time to assess if they now meet criteria for involuntary hold", "Only if family agrees", "None"]', 1, 'This prevents suicidal patients from signing in and then immediately signing out. (MGH Pocket)'),
    (v_topic_id, '138: A patient sues their psychiatrist for malpractice, claiming a medication caused permanent nerve damage. The psychiatrist prescribed the correct FDA-approved dose and documented warning the patient of the risks. Which element of malpractice is MISSING?",', '["Duty", "Dereliction (Breach of Duty). The doctor followed the standard of care.", "Damages", "None"]', 1, 'A bad outcome does not equal malpractice if the standard of care was met. (Kaplan & Sadock)'),
    (v_topic_id, '139: A psychiatrist sleeps with their current patient. Is this malpractice?",', '["No", "Yes, it is always an ethical violation and grounds for losing one''s medical license (breach of fiduciary duty and boundary violation)", "Only if the patient complains", "None"]', 1, 'There is ZERO tolerance for sexual relationships with current patients. (First Aid)'),
    (v_topic_id, '140: A psychiatrist bumps into their patient at the grocery store. The patient says, "Hi Dr. Smith!" How should the doctor respond?",', '["Ignore them", "Say hello back. The doctor cannot initiate contact to protect confidentiality, but if the patient initiates, a brief, polite greeting is appropriate.", "Tell everyone they are a patient", "None"]', 1, 'Follow the patient''s lead regarding public acknowledgment. (MGH Pocket)'),
    (v_topic_id, '141: What is "Folie a deux"?', '["A French dance", "Shared Psychotic Disorder; a delusion develops in an individual in the context of a close relationship with another person who already has the established delusion", "None", "None"]', 1, 'Usually, separating the two individuals cures the "follower." (Kaplan & Sadock)'),
    (v_topic_id, '142: A patient presents with acute, severe panic attack symptoms (palpitations, sweating, fear of dying). What is the FIRST step in the ER?",', '["Give Xanax", "Rule out life-threatening medical mimics (e.g., Myocardial Infarction, Pulmonary Embolism, Arrhythmia) with an ECG and Troponins", "Send to psych", "None"]', 1, 'Never assume panic until medical causes are excluded. (First Aid)'),
    (v_topic_id, '143: A patient with Borderline Personality Disorder slashes their wrists superficially in the waiting room because the doctor was late. They say they don''t want to die, they just "needed to feel something." Is this a suicide attempt?",', '["Yes", "No, this is Non-Suicidal Self-Injury (NSSI). However, it is still a psychiatric emergency requiring medical clearance and acute risk assessment.", "Ignore it", "None"]', 1, 'Intent matters, but safety is the priority. (MGH Pocket)'),
    (v_topic_id, '144: A patient taking MAOIs for depression wants to take an over-the-counter cold medicine. What ingredient MUST they avoid to prevent a Hypertensive Crisis?",', '["Acetaminophen", "Pseudoephedrine or Phenylephrine (sympathomimetics)", "Guaifenesin", "None"]', 1, 'OTC decongestants + MAOIs = extreme hypertension. (Kaplan & Sadock)'),
    (v_topic_id, '145: A patient taking MAOIs for depression wants to take an over-the-counter cough syrup. What ingredient MUST they avoid to prevent Serotonin Syndrome?",', '["Acetaminophen", "Dextromethorphan", "Guaifenesin", "None"]', 1, 'OTC cough suppressant + MAOIs = Serotonin Syndrome. (First Aid)'),
    (v_topic_id, '146: What is the classic triad of Serotonin Syndrome?",', '["Fever, cough, rash", "Altered mental status, autonomic instability (tachycardia, hyperthermia), and neuromuscular hyperactivity (hyperreflexia, clonus)", "None", "None"]', 1, 'Can occur within hours of combining serotonergic drugs. (MGH Pocket)'),
    (v_topic_id, '147: Which opioid is most notorious for causing Serotonin Syndrome when combined with an SSRI?",', '["Morphine", "Tramadol (and Meperidine)", "Codeine", "None"]', 1, 'Tramadol has dual action: mu-opioid agonist AND serotonin/norepinephrine reuptake inhibitor. (Kaplan & Sadock)'),
    (v_topic_id, '148: A patient is prescribed Lithium. They start a new blood pressure medication and return a week later with severe Lithium toxicity. What BP medication did they likely start?",', '["Amlodipine", "A Thiazide Diuretic (e.g., Hydrochlorothiazide), ACE Inhibitor, or ARB", "Beta blocker", "None"]', 1, 'Thiazides cause massive reabsorption of Lithium in the proximal tubule. (First Aid)'),
    (v_topic_id, '149: A patient is prescribed Clozapine. They start smoking cigarettes heavily. What happens to their Clozapine level?",', '["It goes up", "It goes DOWN. Hydrocarbons in tobacco smoke induce CYP1A2, increasing the metabolism of Clozapine.", "It stays the same", "None"]', 1, 'If they stop smoking suddenly in the hospital, their Clozapine level will spike, causing toxicity. (MGH Pocket)'),
    (v_topic_id, '150: A patient with Schizophrenia is brought to the ER with a temperature of 105 F, rigidity, and mutism. They are given Lorazepam and improve dramatically. Was it NMS?",', '["Yes", "No. NMS does not rapidly resolve with a single dose of Lorazepam. This was likely Malignant Catatonia.", "Yes, Lorazepam cures NMS", "None"]', 1, 'A crucial diagnostic distinction. (Kaplan & Sadock)'),
    (v_topic_id, '151: A doctor tells a patient, "If you don''t take this medication, you are going to die." The patient takes it but suffers a severe side effect. What legal concept might the doctor have violated?",', '["Malpractice", "Informed Consent (Coercion invalidates consent)", "Tarasoff", "None"]', 1, 'Consent must be voluntary, not coerced. (First Aid)'),
    (v_topic_id, '152: A patient asks their doctor to help them commit suicide. In states where Physician-Assisted Suicide (PAS) is LEGAL, what is the typical requirement?",', '["A broken leg", "The patient must be a competent adult with a terminal illness (usually < 6 months to live), and they must self-administer the medication", "None", "None"]', 1, 'Strict safeguards exist to prevent abuse. (MGH Pocket)'),
    (v_topic_id, '153: Does a diagnosis of Major Depressive Disorder disqualify a patient from utilizing Physician-Assisted Suicide in states where it is legal?",', '["Yes, automatically", "Not automatically, but the depression must not impair their CAPACITY to make a reasoned decision about their terminal illness", "None", "None"]', 1, 'A complex ethical and clinical intersection. (Kaplan & Sadock)'),
    (v_topic_id, '154: A patient with active, untreated Schizophrenia demands a lung transplant. The transplant team refuses, citing the patient''s inability to adhere to complex post-op regimens. Is this ethical?",', '["No, it is discrimination", "Yes, transplant teams must allocate scarce resources based on medical likelihood of success, and severe untreated mental illness affecting compliance is a valid contraindication", "None", "None"]', 1, 'Once the schizophrenia is treated and stable, they can be relisted. (First Aid)'),
    (v_topic_id, '155: A patient is placed on a 72-hour involuntary hold (e.g., 5150). What happens at the end of the 72 hours if the patient still refuses treatment?",', '["They go home", "They must either be released OR a formal legal hearing (e.g., 5250) must be held before a judge to extend the involuntary commitment", "They are kept forever", "None"]', 1, 'Due process requires a judicial review. (MGH Pocket)'),
    (v_topic_id, '156: What is a "Fitness for Duty" evaluation?",', '["A gym test", "An independent psychiatric evaluation requested by an employer to determine if an employee''s mental health allows them to safely perform their job duties (e.g., an armed police officer)", "None", "None"]', 1, 'The doctor works for the employer, not the patient. (Kaplan & Sadock)'),
    (v_topic_id, '157: In a "Fitness for Duty" or "Forensic" evaluation, what must the psychiatrist tell the individual at the very beginning?",', '["I am your doctor", "That there is NO traditional doctor-patient confidentiality, and the results will be shared with the requesting party (employer/court)", "None", "None"]', 1, 'The "Miranda warning" of forensic psychiatry. (First Aid)'),
    (v_topic_id, '158: A patient in the ER is withdrawing from Heroin. They are miserable but vital signs are stable. Can they die from this?",', '["Yes, immediately", "No. Opioid withdrawal is intensely uncomfortable (feels like a severe flu) but is NOT life-threatening in otherwise healthy adults", "Only if they seize", "None"]', 1, 'Unlike alcohol or benzo withdrawal, which can be fatal. (MGH Pocket)'),
    (v_topic_id, '159: A patient in the ER is withdrawing from Alprazolam (Xanax) after taking 10mg/day for a year. Can they die from this?",', '["No", "Yes. Benzodiazepine withdrawal can cause life-threatening status epilepticus (seizures) and delirium", "Only if they vomit", "None"]', 1, 'Requires medically supervised taper or substitution with a long-acting benzo (Diazepam). (Kaplan & Sadock)'),
    (v_topic_id, '160: A patient with Bipolar Disorder is on Lithium. They go for a 10-mile run in the summer heat and sweat profusely. What happens to their Lithium level?",', '["It decreases", "It INCREASES significantly, potentially causing toxicity, because the kidneys reabsorb Lithium along with sodium in response to dehydration", "It stays the same", "None"]', 1, 'Hydration is critical for patients on Lithium. (First Aid)'),
    (v_topic_id, '161: What is the most rapid way to lower a dangerously high serum Lithium level?",', '["Diuretics", "Hemodialysis", "IV fluids only", "None"]', 1, 'Dialysis removes the ion directly from the blood. (MGH Pocket)'),
    (v_topic_id, '162: A patient presents with acute Lead Poisoning (encephalopathy, abdominal colic, neuropathy). What is the classic finding on a peripheral blood smear?",', '["Sickle cells", "Basophilic stippling of red blood cells", "Schistocytes", "None"]', 1, 'Lead inhibits rRNA degradation. (Kaplan & Sadock)'),
    (v_topic_id, '163: A patient presents with acute agitation and psychosis. They have a history of Wilson''s Disease. What physical exam finding should you look for?",', '["Red eyes", "Kayser-Fleischer rings (brown/copper rings around the cornea in the Descemet membrane)", "Blue sclera", "None"]', 1, 'Copper accumulation in the basal ganglia causes psychiatric symptoms. (First Aid)'),
    (v_topic_id, '164: A patient with acute intermittent porphyria (AIP) presents with severe abdominal pain and psychosis. What triggers these attacks?",', '["Eating sugar", "Certain medications (e.g., Barbiturates, CYP450 inducers), fasting, or stress", "Drinking water", "None"]', 1, 'A classic medical mimic of psychosis. (MGH Pocket)'),
    (v_topic_id, '165: A patient with a known history of Borderline Personality Disorder calls the clinic demanding to speak to the doctor immediately, threatening to cut themselves if the doctor doesn''t answer. What is the best approach?",', '["Hang up", "Brief, clear communication reinforcing boundaries (''''I cannot speak now, but if you are unsafe, go to the ER or call 911''''); do not reinforce the behavior with a long therapy session", "Talk for an hour", "None"]', 1, 'Consistency and boundaries save lives and prevent burnout. (Kaplan & Sadock)'),
    (v_topic_id, '166: A 20-year-old man presents with acute onset of intense paranoia, visual hallucinations of demons, and extreme superhuman strength. He requires 6 security guards to hold him down. Diagnosis?",', '["Schizophrenia", "PCP (Phencyclidine) intoxication", "Depression", "None"]', 1, 'The classic presentation of PCP. (First Aid)'),
    (v_topic_id, '167: A patient on an SSRI presents with hyponatremia. What is the mechanism?",', '["Kidney failure", "SIADH (Syndrome of Inappropriate Antidiuretic Hormone secretion)", "Heart failure", "None"]', 1, 'SSRIs can cause excessive release of ADH. (MGH Pocket)'),
    (v_topic_id, '168: Which of the following is a symptom of severe TCA toxicity?",', '["Bradycardia", "Anticholinergic delirium, widened QRS complex, arrhythmias, and seizures", "Pinpoint pupils", "None"]', 1, 'The "3 Cs": Coma, Convulsions, Cardiotoxicity. (Kaplan & Sadock)'),
    (v_topic_id, '169: A patient presents with priapism. They recently started a medication for sleep and depression. Which medication?",', '["Fluoxetine", "Trazodone", "Mirtazapine", "None"]', 1, 'Alpha-1 adrenergic blockade in the corpus cavernosum. (First Aid)'),
    (v_topic_id, '170: A patient with Schizophrenia has been on Haloperidol for 15 years. They develop twisting, repetitive movements of the tongue and face. What is the pathophysiology?",', '["Dopamine deficiency", "Dopamine D2 receptor UPREGULATION and SUPERSENSITIVITY due to chronic blockade", "Serotonin excess", "None"]', 1, 'This is why stopping the drug suddenly can initially WORSEN the movements. (MGH Pocket)'),
    (v_topic_id, '171: What is the treatment for Tardive Dyskinesia?",', '["Benztropine", "Discontinue offending agent if possible; switch to Clozapine or Quetiapine; or use VMAT2 inhibitors (Valbenazine, Deutetrabenazine)", "Haloperidol", "None"]', 1, 'Anticholinergics (like Benztropine) can actually WORSEN Tardive Dyskinesia. (Kaplan & Sadock)'),
    (v_topic_id, '172: A patient presents with acute dystonia (e.g., locked jaw/trismus). Why should you NOT give them Haloperidol?",', '["It won''t work", "Haloperidol CAUSED the dystonia (it is a high-potency typical antipsychotic). You must give an anticholinergic like Benztropine or Diphenhydramine.", "None", "None"]', 1, 'A fundamental error in management. (First Aid)'),
    (v_topic_id, '173: A patient presents with severe agitation. The resident orders IM Haloperidol, IM Lorazepam, and IM Benztropine simultaneously. Why?",', '["To cause sleep", "This is the classic ''''B52'''' plus prophylactic Benztropine to prevent acute dystonia from the Haloperidol", "To treat pain", "None"]', 1, 'Common practice in emergency psychiatry. (MGH Pocket)'),
    (v_topic_id, '174: A patient has been taking Lithium for 10 years. They present with fatigue, weight gain, and cold intolerance. What test is needed?",', '["ECG", "TSH (Thyroid Stimulating Hormone). Lithium commonly causes hypothyroidism.", "Liver function tests", "None"]', 1, 'Lithium inhibits thyroid hormone release. (Kaplan & Sadock)'),
    (v_topic_id, '175: A patient has been taking Lithium for 10 years. They present with excessive thirst and frequent urination. What is the diagnosis?",', '["Diabetes Mellitus", "Nephrogenic Diabetes Insipidus (Lithium impairs the kidney''s ability to respond to ADH)", "UTI", "None"]', 1, 'A classic long-term renal complication. Treat with Amiloride. (First Aid)'),
    (v_topic_id, '176: A patient is acutely suicidal and requires ECT, but they refuse to sign the consent form due to psychotic delusions. Can ECT be given?",', '["Never", "Yes, but it requires a court order (involuntary ECT) after a judge determines the patient lacks capacity and the treatment is life-saving", "Only if family agrees", "None"]', 1, 'A rigorous legal process protects the patient''s rights. (MGH Pocket)'),
    (v_topic_id, '177: A 6-year-old child is brought to the ER with spiral fractures of the arm and cigarette burns on the back. The parents say the child "fell down the stairs." What is the immediate legal duty?",', '["Discharge home", "Admit the child for safety and immediately file a report with Child Protective Services (CPS) for suspected non-accidental trauma (abuse)", "Call the police only", "None"]', 1, 'Medical providers are mandatory reporters. (Kaplan & Sadock)'),
    (v_topic_id, '178: What is "Assault" in a medical context?",', '["Hitting a patient", "Placing a patient in reasonable fear of imminent harmful or offensive contact (e.g., threatening to inject them if they don''t comply)", "None", "None"]', 1, 'Assault is the THREAT. (First Aid)'),
    (v_topic_id, '179: What is "Battery" in a medical context?",', '["Threatening a patient", "Intentional, unconsented harmful or offensive physical contact (e.g., performing a surgery the patient explicitly refused)", "None", "None"]', 1, 'Battery is the ACTION. (MGH Pocket)'),
    (v_topic_id, '180: A surgeon performs a life-saving appendectomy on an unconscious, unaccompanied John Doe in the ER. The patient wakes up and sues for battery. Will the patient win?",', '["Yes", "No. The doctrine of implied consent protects physicians in emergencies where a reasonable person would want the intervention", "Only if he is rich", "None"]', 1, 'The law recognizes the preservation of life in emergencies. (Kaplan & Sadock)'),
    (v_topic_id, '181: A patient with severe dementia and no advance directive needs a feeding tube. The patient''s spouse wants it, but the adult children do NOT want it. Who legally gets to decide?",', '["The doctor", "The spouse. In the hierarchy of surrogate decision-makers, the spouse supersedes adult children.", "The oldest child", "None"]', 1, 'Know the surrogate hierarchy: Spouse > Adult Children > Parents > Siblings. (First Aid)'),
    (v_topic_id, '182: A patient has a living will stating "Do Not Resuscitate" (DNR). The patient goes into cardiac arrest. The patient''s wife screams at you to do CPR. What do you do?",', '["Do CPR", "Do NOT perform CPR. A valid advance directive (DNR) executed while the patient had capacity supersedes the wishes of the surrogate.", "Call a lawyer", "None"]', 1, 'The patient''s prior autonomous choice is paramount. (MGH Pocket)'),
    (v_topic_id, '183: What is "Beneficence"?', '["Doing no harm", "The ethical principle of acting in the best interest of the patient", "Telling the truth", "None"]', 1, 'The foundation of medical care. (Kaplan & Sadock)'),
    (v_topic_id, '184: What is "Non-maleficence"?', '["Doing good", "The ethical principle of ''''First, do no harm'''' (Primum non nocere)", "Being fair", "None"]', 1, 'Avoid unnecessary risks or toxicities. (First Aid)'),
    (v_topic_id, '185: What is "Autonomy"?', '["Being independent", "The ethical principle respecting a patient''s right to self-determination and to make their own medical decisions (if they have capacity)", "None", "None"]', 1, 'The basis for informed consent. (MGH Pocket)'),
    (v_topic_id, '186: What is "Justice" in medical ethics?",', '["Punishing bad doctors", "The ethical principle of fair and equitable distribution of health resources", "Telling the truth", "None"]', 1, 'Relevant in triage and organ allocation. (Kaplan & Sadock)'),
    (v_topic_id, '187: A patient asks, "Do I have cancer?" You know they do, but their family asked you not to tell them because it will "break their heart." What ethical principle demands you tell the patient the truth?",', '["Justice", "Autonomy and Veracity (truth-telling). Patients have a right to know their diagnosis to make informed decisions.", "Non-maleficence", "None"]', 1, 'Therapeutic privilege to withhold information is extremely rare and only applies if the information would cause severe psychological harm (e.g., immediate suicide). (First Aid)'),
    (v_topic_id, '188: A patient presents to the ER with extreme agitation, picking at their skin, and complaining of feeling "bugs crawling" under the skin. Their teeth are severely decayed ("meth mouth"). Diagnosis?",', '["Cocaine toxicity", "Methamphetamine toxicity", "Opioid withdrawal", "None"]', 1, 'Meth causes extreme bruxism and poor hygiene leading to rapid dental decay. (MGH Pocket)'),
    (v_topic_id, '189: A patient presents with acute panic, tachycardia, and a feeling that they are going to die after smoking marijuana. What is the treatment?",', '["Haloperidol", "Reassurance and a quiet environment. Short-acting benzodiazepines can be used if severe.", "Naloxone", "None"]', 1, 'Cannabis-induced anxiety is usually self-limiting. (Kaplan & Sadock)'),
    (v_topic_id, '190: A patient snorts a white powder and presents with euphoria, tachycardia, pupillary dilation, and chest pain. An ECG shows ST elevation. Diagnosis?",', '["Heroin", "Cocaine-induced coronary vasospasm leading to myocardial ischemia/infarction", "PCP", "None"]', 1, 'Cocaine acts as a potent vasoconstrictor and increases myocardial oxygen demand. (First Aid)'),
    (v_topic_id, '191: How do you treat cocaine-induced chest pain?",', '["Propranolol", "Oxygen, Benzodiazepines (to decrease sympathetic drive), Aspirin, and Nitroglycerin/Calcium Channel Blockers for vasodilation", "Nothing", "None"]', 1, 'Beta-blockers are contraindicated. (MGH Pocket)'),
    (v_topic_id, '192: A teenager is brought in by parents who found him inhaling glue/paint thinner (inhalants). What is the most immediate life-threatening risk?",', '["Liver failure", "Sudden Sniffing Death Syndrome (fatal cardiac arrhythmias sensitized by the halogenated hydrocarbons)", "Blindness", "None"]', 1, 'Inhalants make the heart exquisitely sensitive to catecholamines. (Kaplan & Sadock)'),
    (v_topic_id, '193: A patient uses synthetic cannabinoids ("Spice" or "K2"). How does their presentation differ from natural marijuana?",', '["It is the same", "Synthetic cannabinoids are full agonists (not partial) and can cause severe agitation, psychosis, seizures, and acute kidney injury", "It is milder", "None"]', 1, 'Much more dangerous than natural THC. (First Aid)'),
    (v_topic_id, '194: A patient presents with acute onset of severe depression, anhedonia, hypersomnolence (sleeping 18 hours a day), and massive hyperphagia (eating everything). They recently stopped using a drug. Which drug?",', '["Heroin", "Cocaine or Amphetamines (the ''''Crash'''')", "Alcohol", "None"]', 1, 'Stimulant withdrawal looks like atypical depression. (MGH Pocket)'),
    (v_topic_id, '195: A patient is brought to the ER after a suicide attempt via carbon monoxide poisoning (running the car in a closed garage). They have a cherry-red appearance to their skin. What is the immediate treatment?",', '["Naloxone", "100% Oxygen via non-rebreather mask (or Hyperbaric Oxygen for severe cases/pregnant women)", "Flumazenil", "None"]', 1, 'Oxygen competitively displaces CO from hemoglobin. (Kaplan & Sadock)'),
    (v_topic_id, '196: A patient taking Clozapine develops myocarditis. What is the appropriate action?",', '["Lower the dose", "Immediately and permanently DISCONTINUE Clozapine; it is a potentially fatal complication", "Give beta blockers", "None"]', 1, 'A black box warning for Clozapine alongside agranulocytosis. (First Aid)'),
    (v_topic_id, '197: A patient in the ER is hyperventilating due to a severe panic attack. They complain of tingling in their lips and fingers (carpopedal spasm). What is the pathophysiology?",', '["Hypoxia", "Hyperventilation causes Respiratory Alkalosis, which leads to decreased ionized calcium (hypocalcemia), causing the tingling/spasms", "Heart attack", "None"]', 1, 'Breathing into a paper bag restores CO2. (MGH Pocket)'),
    (v_topic_id, '198: A patient is deemed a danger to others and is placed on an involuntary hold. They demand to speak to a lawyer. Do they have this right?",', '["No", "Yes, involuntary patients retain their civil rights, including the right to legal counsel and to contest their commitment (Habeas Corpus)", "Only after 72 hours", "None"]', 1, 'Psychiatric commitment is not a suspension of constitutional rights. (Kaplan & Sadock)'),
    (v_topic_id, '199: A physician suspects a colleague is practicing medicine while intoxicated. What is their ethical and legal obligation?",', '["Ignore it", "Report the colleague to the physician health program or state medical board to protect patients from harm", "Tell the colleague''s spouse", "None"]', 1, 'Patient safety is the absolute highest priority. (First Aid)'),
    (v_topic_id, '200: Final Pearl: In any psychiatric emergency involving agitation or altered mental status, what is ALWAYS step one?",', '["Give Haloperidol", "Ensure the SAFETY of the patient and staff, then rule out life-threatening MEDICAL causes (ABCs, vitals, glucose, hypoxia, tox screen)", "Call psychiatry", "None"]', 1, 'Psychiatry begins only after medicine has cleared the patient. (MediHelp Mastery)'),
    (v_topic_id, '201: A patient states they intend to kill their spouse and has a specific plan. Under Tarasoff, what action must the psychiatrist take?', '["Only warn the spouse", "Warn the spouse AND notify law enforcement", "Keep it confidential", "None"]', 1, 'Duty to protect often requires both warning the victim and notifying police. (Kaplan & Sadock)'),
    (v_topic_id, '202: Which of the following is NOT an exception to confidentiality?', '["Suspected child abuse", "Court order", "Patient is a danger to others", "A spouse requesting medical records for a divorce proceeding"]', 3, 'A spouse has no right to records without the patient''s written consent or a court order. (First Aid)'),
    (v_topic_id, '203: A 15-year-old requests birth control pills. Does she need parental consent in most states?', '["Yes", "No", "Only if she is pregnant", "None"]', 1, 'Minors can usually consent to contraception, STD treatment, and prenatal care without parental involvement. (MGH Pocket)'),
    (v_topic_id, '204: A patient with schizophrenia refuses a blood draw because they believe the needle contains a tracking device. Do they have capacity to refuse this procedure?', '["Yes", "No", "Only if they are involuntarily committed", "None"]', 1, 'Their refusal is based on a delusion, indicating a lack of understanding of the true nature of the procedure. (Kaplan & Sadock)'),
    (v_topic_id, '205: A physician performs a procedure without obtaining informed consent. The procedure goes perfectly and the patient is cured. Can the physician be sued?', '["No, because there were no damages", "Yes, for battery (unconsented touching)", "Yes, for malpractice", "None"]', 1, 'Battery does not require damages, only unconsented contact. (First Aid)'),
    (v_topic_id, '206: What is the most common method of completed suicide in the United States?', '["Poisoning", "Firearms", "Hanging", "None"]', 1, 'Accounts for more than 50% of completed suicides. (MGH Pocket)'),
    (v_topic_id, '207: A patient is pacing the ER, yelling, and clenching their fists. What is the best initial approach to de-escalate the situation?', '["Immediate physical restraints", "Verbal de-escalation in a calm, non-confrontational manner, offering choices and respecting personal space", "IM Haloperidol", "None"]', 1, 'Verbal de-escalation is always the first step unless there is imminent violence. (Kaplan & Sadock)'),
    (v_topic_id, '208: Which combination of medications is commonly used for chemical restraint of a highly agitated, violent patient?', '["Fluoxetine and Lithium", "Haloperidol, Lorazepam, and Diphenhydramine (or Benztropine)", "Clozapine and Valproate", "None"]', 1, 'The "B52" combination provides rapid tranquilization and prevents dystonia. (First Aid)'),
    (v_topic_id, '209: A patient on Olanzapine develops a fever of 105F, severe rigidity, and elevated CK. What is the diagnosis?', '["Serotonin Syndrome", "Neuroleptic Malignant Syndrome (NMS)", "Catatonia", "None"]', 1, 'Classic presentation of NMS triggered by dopamine antagonism. (MGH Pocket)'),
    (v_topic_id, '210: A patient taking Phenelzine (an MAOI) eats a large amount of aged cheese. What life-threatening condition are they at risk for?', '["Serotonin Syndrome", "Hypertensive Crisis", "NMS", "None"]', 1, 'Due to the buildup of tyramine, which acts as a sympathomimetic. (Kaplan & Sadock)'),
    (v_topic_id, '211: A patient intentionally overdoses on Amitriptyline (a TCA). They present with a widened QRS complex. What is the immediate treatment?",', '["Naloxone", "IV Sodium Bicarbonate", "Flumazenil", "None"]', 1, 'Overcomes the sodium channel blockade caused by the TCA. (First Aid)'),
    (v_topic_id, '212: A patient presents to the ER with constricted (pinpoint) pupils, respiratory rate of 6/min, and profound sedation. What is the most appropriate first medication to administer?",', '["Flumazenil", "Naloxone", "Haloperidol", "None"]', 1, 'Classic opioid overdose requires immediate reversal to save the airway. (MGH Pocket)'),
    (v_topic_id, '213: A patient is brought to the ER with hallucinations of "bugs crawling on the walls," profound tachycardia, sweating, and tremors 72 hours after their last alcoholic drink. Diagnosis?",', '["Opioid withdrawal", "Delirium Tremens (severe alcohol withdrawal)", "Schizophrenia", "None"]', 1, 'A medical emergency requiring high-dose benzodiazepines. (Kaplan & Sadock)'),
    (v_topic_id, '214: A patient presents with acute onset of severe agitation, combativeness, rotary nystagmus, and reduced pain perception. What substance did they likely use?",', '["Cocaine", "Phencyclidine (PCP)", "Heroin", "None"]', 1, 'Rotary or vertical nystagmus is the classic physical exam finding for PCP. (First Aid)'),
    (v_topic_id, '215: A patient with severe anorexia nervosa (BMI 12) is admitted and started on high-calorie tube feeds. They develop acute heart failure and severe hypophosphatemia. Diagnosis?",', '["NMS", "Refeeding Syndrome", "Bulimia", "None"]', 1, 'Rapid reintroduction of carbohydrates causes a massive insulin surge, depleting intracellular phosphate. (MGH Pocket)'),
    (v_topic_id, '216: A physician suspects a child is being physically abused but does not have conclusive proof. What should the physician do?",', '["Wait for more evidence", "Report the suspicion to Child Protective Services immediately", "Confront the parents", "None"]', 1, 'Physicians are mandatory reporters; suspicion is enough. (Kaplan & Sadock)'),
    (v_topic_id, '217: A patient with severe major depressive disorder is placed on a 72-hour involuntary hold (5150) because they are actively suicidal. At the end of the 72 hours, they still refuse treatment and remain suicidal. What happens next?",', '["They must be discharged", "A formal hearing must be held to determine if the hold should be extended (e.g., a 14-day hold)", "They are committed permanently", "None"]', 1, 'Due process requires legal review to extend involuntary commitment. (First Aid)'),
    (v_topic_id, '218: A patient presents with acute dystonia (e.g., a locked jaw) after receiving Haloperidol. What medication should be given immediately?",', '["More Haloperidol", "IM Benztropine or Diphenhydramine", "Lorazepam", "None"]', 1, 'Anticholinergics rapidly reverse the dopamine blockade causing the dystonia. (MGH Pocket)'),
    (v_topic_id, '219: A patient who has been taking Risperidone for 5 years presents with constant, involuntary lip-smacking and tongue protrusion. Diagnosis?",', '["Acute dystonia", "Tardive Dyskinesia", "Akathisia", "None"]', 1, 'A long-term complication of dopamine receptor blockade. (Kaplan & Sadock)'),
    (v_topic_id, '220: A patient taking Lithium presents with coarse tremors, ataxia, vomiting, and confusion. What is the most important initial test?",', '["CT scan of the head", "Serum Lithium level, BMP (for renal function), and ECG", "Liver function tests", "None"]', 1, 'Symptoms are classic for Lithium toxicity. (First Aid)'),
    (v_topic_id, '221: A 25-year-old man presents with paranoia, grandiosity, tachycardia, and dilated pupils. He has a history of substance abuse. Diagnosis?",', '["Schizophrenia", "Cocaine or Methamphetamine Intoxication", "Opioid withdrawal", "None"]', 1, 'Stimulant intoxication mimics acute mania or psychosis. (MGH Pocket)'),
    (v_topic_id, '222: A patient with Wernicke''s Encephalopathy must receive which vitamin IMMEDIATELY before any glucose is administered?",', '["Vitamin C", "Vitamin B1 (Thiamine)", "Vitamin B12", "None"]', 1, 'Glucose without thiamine will precipitate Korsakoff''s syndrome. (Kaplan & Sadock)'),
    (v_topic_id, '223: What is the defining characteristic of Factitious Disorder?",', '["Faking symptoms for financial gain", "Intentional production or feigning of symptoms to assume the sick role, without obvious external rewards", "A delusion of being sick", "None"]', 1, 'Malingering is for external gain; Factitious is for internal psychological needs. (First Aid)'),
    (v_topic_id, '224: A patient demands a specific medication and threatens to sue the doctor if it is not prescribed. What should the doctor do?",', '["Prescribe it to avoid a lawsuit", "Refuse to prescribe if it is not medically indicated, document the encounter, and maintain professional boundaries", "Call the police", "None"]', 1, 'Physicians are not obligated to provide non-indicated treatments. (MGH Pocket)'),
    (v_topic_id, '225: A patient is involuntarily committed because they are a danger to others. They demand to speak to a lawyer. Do they have this right?",', '["No, they lost their rights when committed", "Yes, involuntary patients retain their civil rights, including access to counsel", "Only if they pay for it", "None"]', 1, 'Commitment does not strip a patient of their basic constitutional rights. (Kaplan & Sadock)'),
    (v_topic_id, '226: A patient with a history of severe alcohol abuse wants to stop drinking. Which medication causes a severe physical reaction (nausea, vomiting, flushing) if they consume alcohol?",', '["Naltrexone", "Disulfiram (Antabuse)", "Acamprosate", "None"]', 1, 'Aversive therapy via aldehyde dehydrogenase inhibition. (First Aid)'),
    (v_topic_id, '227: A patient is prescribed Clozapine. They develop a severe sore throat and fever. What is the most critical lab value to check?",', '["Hemoglobin", "Absolute Neutrophil Count (ANC)", "Platelets", "None"]', 1, 'Agranulocytosis is a fatal complication of Clozapine. (MGH Pocket)'),
    (v_topic_id, '228: A patient taking an SSRI and a Triptan (for migraines) presents with agitation, hyperreflexia, clonus, and diaphoresis. Diagnosis?",', '["NMS", "Serotonin Syndrome", "Anticholinergic toxicity", "None"]', 1, 'Both medications increase serotonergic activity. (Kaplan & Sadock)'),
    (v_topic_id, '229: What is the initial treatment of choice for Serotonin Syndrome?",', '["Haloperidol", "Discontinue offending agents and provide supportive care (cooling, IV fluids, benzodiazepines)", "Lithium", "None"]', 1, 'Cyproheptadine can be used in severe cases. (First Aid)'),
    (v_topic_id, '230: A patient with Bipolar Disorder is stabilized on Valproic Acid. They present with acute abdominal pain and vomiting. What serious side effect must be ruled out?",', '["Appendicitis", "Valproate-induced Pancreatitis or Hepatotoxicity", "Kidney stones", "None"]', 1, 'Check amylase, lipase, and liver enzymes. (MGH Pocket)'),
    (v_topic_id, '231: A patient taking Lamotrigine develops a rapidly spreading rash with blistering and mucosal involvement. What is the diagnosis?",', '["Psoriasis", "Stevens-Johnson Syndrome (SJS)", "Acne", "None"]', 1, 'A dermatologic emergency requiring immediate discontinuation of the drug. (Kaplan & Sadock)'),
    (v_topic_id, '232: A patient presents to the ER with extreme agitation, picking at their skin ("bugs"), and severe dental decay. What substance are they likely abusing?",', '["Cocaine", "Methamphetamine", "Heroin", "None"]', 1, '"Meth mouth" and tactile hallucinations (formication) are classic. (First Aid)'),
    (v_topic_id, '233: A patient is brought to the ER after a suicide attempt by hanging. They are unconscious and breathing poorly. What is the first priority?",', '["Assess their suicide risk", "Airway, Breathing, Circulation (ABCs) - intubate if necessary", "Call psychiatry", "None"]', 1, 'Medical stabilization ALWAYS precedes psychiatric evaluation. (MGH Pocket)'),
    (v_topic_id, '234: A patient with severe depression refuses to eat or drink for weeks and is medically unstable. They refuse ECT. Can ECT be administered against their will?",', '["No, never", "Yes, but only after a formal legal process (court order) determines they lack capacity and the treatment is life-saving", "Yes, if the family agrees", "None"]', 1, 'Involuntary ECT is possible but highly regulated. (Kaplan & Sadock)'),
    (v_topic_id, '235: A psychiatrist is attracted to a patient. Can the psychiatrist date the patient after terminating the doctor-patient relationship?",', '["Yes, immediately", "Generally NO; most ethical guidelines state that sexual relationships with former psychiatric patients are always unethical due to the inherent power dynamic", "Yes, after 1 year", "None"]', 1, 'The power differential persists long after treatment ends. (First Aid)'),
    (v_topic_id, '236: A patient asks to see their medical chart. The psychiatrist believes reading the chart will cause the patient severe psychological harm and precipitate a suicide attempt. Can the psychiatrist withhold the chart?",', '["No, never", "Yes, under the doctrine of ''''Therapeutic Privilege,'''' though this is an extremely rare and difficult to justify exception", "Yes, always", "None"]', 1, 'This exception is very narrowly applied. (MGH Pocket)'),
    (v_topic_id, '237: A patient presents with acute opioid withdrawal (nausea, muscle aches, yawning, lacrimation). What is the appropriate initial management?",', '["Naloxone", "Supportive care (e.g., Clonidine, antiemetics, NSAIDs) or initiation of Medication-Assisted Treatment (Buprenorphine/Methadone)", "Haloperidol", "None"]', 1, 'Withdrawal is not life-threatening but requires symptomatic relief. (Kaplan & Sadock)'),
    (v_topic_id, '238: A patient is acutely intoxicated with alcohol and highly aggressive. Why should you avoid giving them a Benzodiazepine for sedation?",', '["It won''t work", "Combining two CNS depressants (alcohol + benzo) can cause fatal respiratory depression", "It causes mania", "None"]', 1, 'Use an antipsychotic like Haloperidol if chemical restraint is absolutely necessary. (First Aid)'),
    (v_topic_id, '239: A patient presents with acute delirium (fluctuating consciousness, disorganized thinking). What is the most critical first step?",', '["Psychiatric admission", "A thorough medical workup to identify and treat the underlying medical cause (e.g., infection, metabolic derangement, tox)", "Prescribe an SSRI", "None"]', 1, 'Delirium is a medical emergency. (MGH Pocket)'),
    (v_topic_id, '240: Which of the following medications is most likely to cause delirium in an elderly patient?",', '["Sertraline", "Diphenhydramine (or any medication with strong anticholinergic properties)", "Acetaminophen", "None"]', 1, 'Elderly patients are exquisitely sensitive to anticholinergic effects. (Kaplan & Sadock)'),
    (v_topic_id, '241: A patient taking a high-potency typical antipsychotic (like Haloperidol) is at greatest risk for which side effect?",', '["Weight gain", "Extrapyramidal Symptoms (EPS) such as dystonia, parkinsonism, and akathisia", "Sedation", "None"]', 1, 'High potency = high D2 blockade = high EPS risk. (First Aid)'),
    (v_topic_id, '242: A patient taking a low-potency typical antipsychotic (like Chlorpromazine) is at greatest risk for which side effects?",', '["EPS", "Anticholinergic effects (dry mouth, constipation), sedation, and orthostatic hypotension", "Weight loss", "None"]', 1, 'Low potency = high off-target receptor blockade (H1, M1, Alpha-1). (MGH Pocket)'),
    (v_topic_id, '243: A patient taking an atypical antipsychotic (like Olanzapine) is at greatest risk for which side effects?",', '["EPS", "Metabolic Syndrome (weight gain, hyperlipidemia, hyperglycemia)", "Tardive dyskinesia", "None"]', 1, 'Routine monitoring of weight, lipids, and A1c is required. (Kaplan & Sadock)'),
    (v_topic_id, '244: A patient with a history of severe depression and a previous suicide attempt is starting an SSRI. What is the most important warning to give them?",', '["It will cause weight gain", "There may be an INCREASED risk of suicidal thoughts during the first few weeks of treatment", "It will cause hair loss", "None"]', 1, 'The classic black box warning for antidepressants in young adults. (First Aid)'),
    (v_topic_id, '245: A patient with bipolar disorder is manic and refusing medication. They are spending all their money and engaging in risky sexual behavior, but are NOT imminently threatening to harm anyone. Can they be involuntarily committed?",', '["No", "Yes, if their behavior meets the criteria for ''''Grave Disability'''' (unable to provide for basic needs due to mental illness) or if local laws allow commitment for severe deterioration", "Only if they commit a crime", "None"]', 1, 'The threshold for involuntary commitment varies by state but often includes severe deterioration. (MGH Pocket)'),
    (v_topic_id, '246: A patient presents with acute catatonia. You give them a Lorazepam challenge, and they do NOT respond. What is the next best treatment?",', '["Haloperidol", "Electroconvulsive Therapy (ECT)", "Fluoxetine", "None"]', 1, 'ECT is highly effective for treatment-resistant catatonia. (Kaplan & Sadock)'),
    (v_topic_id, '247: A patient taking Lithium develops severe polyuria and polydipsia. What is the most likely cause?",', '["Diabetes Mellitus", "Nephrogenic Diabetes Insipidus caused by Lithium", "UTI", "None"]', 1, 'Lithium interferes with ADH action in the collecting duct. (First Aid)'),
    (v_topic_id, '248: A patient is brought to the ER after a suicide attempt via Acetaminophen overdose. What is the most important lab value to trend over the next few days?",', '["BUN/Creatinine", "Liver Function Tests (AST/ALT) and Coagulation studies (PT/INR) to monitor for hepatic failure", "Troponin", "None"]', 1, 'Acetaminophen toxicity causes massive centrilobular hepatic necrosis. (MGH Pocket)'),
    (v_topic_id, '249: A patient presents with pinpoint pupils, respiratory depression, and coma. You suspect opioid overdose, but they do not respond to Naloxone. What other substance should be suspected?",', '["Cocaine", "Clonidine (an alpha-2 agonist) overdose closely mimics opioid overdose", "Methamphetamine", "None"]', 1, 'A classic toxicology pearl. (Kaplan & Sadock)'),
    (v_topic_id, '250: A patient with severe social anxiety disorder needs to give a public speech. What medication can be taken PRN to reduce the autonomic symptoms of anxiety (tachycardia, tremor) without causing sedation?",', '["Alprazolam", "Propranolol (a beta-blocker)", "Fluoxetine", "None"]', 1, 'Effective for performance anxiety. (First Aid)'),
    (v_topic_id, '251: A patient is acutely suicidal and refusing all food and fluids. They are rapidly deteriorating. The family refuses to consent to ECT. Can the hospital proceed with ECT?', '["No, family consent is absolute", "Yes, through an emergency court order if the treatment is deemed life-saving and the patient lacks capacity", "Only with 2 psychiatrists'' approval", "None"]', 1, 'In extreme emergencies, the state can intervene to preserve life over surrogate refusal. (MGH Pocket)'),
    (v_topic_id, '252: A 30-year-old woman with severe postpartum depression and psychosis believes her baby is possessed and plans to harm him. What is the immediate legal and clinical step?', '["Prescribe an SSRI and discharge", "Immediate involuntary psychiatric hospitalization and separation from the baby to ensure safety", "Call her husband", "None"]', 1, 'Postpartum psychosis with thoughts of harm is a dire psychiatric emergency. (Kaplan & Sadock)'),
    (v_topic_id, '253: A patient is brought in by police after being found wandering naked in the street during a blizzard. They are mute and appear internally preoccupied. They are placed on an involuntary hold for:', '["Danger to others", "Grave Disability (inability to provide for basic needs like shelter/clothing due to mental illness)", "Danger to self", "None"]', 1, 'Wandering in a blizzard without clothes is a classic example of grave disability. (First Aid)'),
    (v_topic_id, '254: During a code white (violent patient), a patient bites a nurse, breaking the skin. What must the hospital do?', '["Fire the nurse", "Follow post-exposure prophylaxis protocols for bloodborne pathogens (HIV, Hepatitis B/C) for the nurse and test the patient if legally permitted", "Sue the patient", "None"]', 1, 'Occupational health hazard requiring immediate medical protocol. (MGH Pocket)'),
    (v_topic_id, '255: A patient taking Clozapine is found unresponsive with a heart rate of 30 and severe hypotension. An ECG reveals complete heart block. This is a rare presentation of:', '["Agranulocytosis", "Clozapine-induced Myocarditis/Cardiomyopathy", "NMS", "None"]', 1, 'Myocarditis can present rapidly and be fatal. (Kaplan & Sadock)'),
    (v_topic_id, '256: A patient with a history of IV drug use presents with acute onset of bilateral leg weakness, urinary retention, and fever. What is the most critical diagnosis to rule out?",', '["Guillain-Barre syndrome", "Spinal Epidural Abscess", "Multiple Sclerosis", "None"]', 1, 'A neurosurgical emergency; requires emergent MRI of the spine. (First Aid)'),
    (v_topic_id, '257: A patient who ingested a large amount of a liquid from their garage presents with profound metabolic acidosis, visual changes ("snowstorm" vision), and blindness. What did they ingest?",', '["Ethylene glycol", "Methanol (wood alcohol)", "Isopropyl alcohol", "None"]', 1, 'Methanol causes retinal toxicity. Antidote is Fomepizole or Ethanol. (MGH Pocket)'),
    (v_topic_id, '258: A patient ingests isopropyl alcohol (rubbing alcohol). They are intoxicated but lack the severe metabolic acidosis seen with methanol. What unique finding might be present in their breath/urine?",', '["Garlic odor", "Fruity odor (due to acetone metabolite)", "Bitter almond odor", "None"]', 1, 'Isopropyl alcohol is metabolized to acetone (a ketone). (Kaplan & Sadock)'),
    (v_topic_id, '259: A patient presents with flushed skin, a cherry-red appearance, headache, and confusion after being rescued from a house fire. What toxicity must be suspected?",', '["Cyanide poisoning", "Carbon Monoxide (CO) poisoning", "Lead poisoning", "None"]', 1, 'CO binds to hemoglobin with 200x the affinity of oxygen. (First Aid)'),
    (v_topic_id, '260: A patient rescued from a house fire presents with profound lactic acidosis, coma, and a "bitter almond" smell on their breath. What is the suspected toxicity?",', '["Carbon Monoxide", "Cyanide Poisoning (from burning plastics/synthetic materials)", "Arsenic", "None"]', 1, 'Cyanide blocks cytochrome c oxidase in the mitochondria. (MGH Pocket)'),
    (v_topic_id, '261: What is the antidote kit for Cyanide Poisoning?",', '["Naloxone", "Hydroxocobalamin or the Cyanide Antidote Kit (Amyl nitrite, Sodium nitrite, Sodium thiosulfate)", "Flumazenil", "None"]', 1, 'Hydroxocobalamin binds cyanide directly to form non-toxic cyanocobalamin (Vitamin B12). (Kaplan & Sadock)'),
    (v_topic_id, '262: A patient presents with severe agitation, hyperthermia, and dilated pupils after taking a "designer drug." They develop severe hyponatremia and a seizure. What drug did they likely take?",', '["Cocaine", "MDMA (Ecstasy/Molly)", "Heroin", "None"]', 1, 'MDMA increases ADH release, leading to severe hyponatremia. (First Aid)'),
    (v_topic_id, '263: A patient who chronically abuses Nitrous Oxide (whip-its) presents with numbness in their legs, ataxia, and a megaloblastic anemia. What vitamin deficiency does this mimic?",', '["Vitamin C", "Vitamin B12 (Cobalamin)", "Vitamin B1", "None"]', 1, 'Nitrous oxide oxidizes and inactivates Vitamin B12. (MGH Pocket)'),
    (v_topic_id, '264: A patient taking an SSRI presents with increased bleeding/bruising. What is the mechanism?",', '["Liver failure", "SSRIs deplete serotonin in platelets, impairing platelet aggregation", "Bone marrow suppression", "None"]', 1, 'Use caution when combining SSRIs with NSAIDs or anticoagulants. (Kaplan & Sadock)'),
    (v_topic_id, '265: A patient with Bipolar Disorder is admitted with an acute myocardial infarction. The cardiologist wants to start high-dose Aspirin and Clopidogrel. The patient is currently on Lithium. Is this combination safe?",', '["Yes, completely", "No, Aspirin does not generally affect Lithium levels, but extreme caution is needed if other NSAIDs are used for pain", "None", "None"]', 1, 'Aspirin and Acetaminophen are generally safe with Lithium, unlike Ibuprofen or Naproxen. (First Aid)'),
    (v_topic_id, '266: A physician refuses to treat a patient because the patient is HIV positive. What ethical principle is violated?",', '["Autonomy", "Justice (fairness and non-discrimination in providing care)", "Veracity", "None"]', 1, 'Physicians cannot refuse care solely based on discriminatory factors. (MGH Pocket)'),
    (v_topic_id, '267: A patient demands a medically unnecessary and potentially harmful surgery (e.g., amputating a healthy limb). Must the surgeon comply?",', '["Yes, autonomy", "No, the principle of Non-Maleficence (do no harm) overrides the patient''s autonomy in demanding harmful, non-indicated procedures", "Only if paid in cash", "None"]', 1, 'Autonomy is a negative right (right to refuse), not a positive right (right to demand). (Kaplan & Sadock)'),
    (v_topic_id, '268: A patient is enrolled in a clinical trial for a new antipsychotic. Halfway through, they want to withdraw. The researcher tells them they cannot leave until the trial is over. Is this ethical?",', '["Yes", "No, participants have the absolute right to withdraw from research at any time without penalty", "Only if they get sick", "None"]', 1, 'A fundamental principle of research ethics (Declaration of Helsinki). (First Aid)'),
    (v_topic_id, '269: What is "Therapeutic Privilege"?', '["A doctor''s right to get paid", "The rare ethical and legal exception allowing a physician to withhold diagnostic information if disclosing it would cause severe, immediate psychological harm (e.g., precipitating a suicide)", "None", "None"]', 1, 'Cannot be used just to spare a patient "bad news." (MGH Pocket)'),
    (v_topic_id, '270: A patient with severe dementia and no surrogate decision-maker needs a non-emergent, elective surgery. Who gives consent?",', '["The primary care doctor", "A court-appointed guardian must be obtained", "The surgeon", "None"]', 1, 'Doctors cannot consent for elective procedures on incompetent patients without a surrogate or guardian. (Kaplan & Sadock)'),
    (v_topic_id, '271: A teenager is admitted after a suicide attempt. The parents demand to see the patient''s psychotherapy notes. Are psychotherapy notes protected under HIPAA?",', '["No", "Yes, psychotherapy notes are afforded special protection under HIPAA and generally cannot be released without the patient''s specific authorization, even to parents", "Only if the patient is 18", "None"]', 1, 'This encourages open communication in therapy. (First Aid)'),
    (v_topic_id, '272: A patient leaves the hospital Against Medical Advice (AMA). They later sue the hospital for a bad outcome related to their early departure. Does an AMA form completely protect the hospital?",', '["Yes, absolutely", "No, an AMA form is helpful evidence, but the hospital can still be sued if they failed to assess capacity or adequately explain the risks before the patient left", "None", "None"]', 1, 'Thorough documentation of the capacity assessment and risk discussion is essential. (MGH Pocket)'),
    (v_topic_id, '273: A patient with Schizophrenia is stabilized on Haloperidol but develops severe, painful muscle spasms of the neck (torticollis). Diagnosis?",', '["Tardive dyskinesia", "Acute Dystonia", "Akathisia", "None"]', 1, 'Treat with IM Benztropine or Diphenhydramine. (Kaplan & Sadock)'),
    (v_topic_id, '274: A patient taking Fluphenazine develops intense inner restlessness and pacing. Diagnosis?",', '["Mania", "Akathisia", "Parkinsonism", "None"]', 1, 'Treat with Beta-blockers (Propranolol). (First Aid)'),
    (v_topic_id, '275: A patient taking Chlorpromazine develops a shuffling gait, resting tremor, and cogwheel rigidity. Diagnosis?",', '["Huntington''s", "Antipsychotic-induced Parkinsonism", "Tardive dyskinesia", "None"]', 1, 'Treat by lowering the dose or adding an anticholinergic (Benztropine) or Amantadine. (MGH Pocket)'),
    (v_topic_id, '276: A patient with a history of long-term Risperidone use develops repetitive, involuntary movements of the mouth and tongue. Diagnosis?",', '["Acute dystonia", "Tardive Dyskinesia", "Akathisia", "None"]', 1, 'Treat by discontinuing the drug if possible or switching to Clozapine. VMAT2 inhibitors can also be used. (Kaplan & Sadock)'),
    (v_topic_id, '277: A patient taking Valproic Acid presents with jaundice, right upper quadrant pain, and elevated AST/ALT. Diagnosis?",', '["Hepatitis A", "Valproate-induced Hepatotoxicity", "Pancreatitis", "None"]', 1, 'A black box warning for Valproate. (First Aid)'),
    (v_topic_id, '278: A patient taking Carbamazepine presents with severe sore throat, fever, and mouth ulcers. CBC shows an absolute neutrophil count of 100. Diagnosis?",', '["Viral URI", "Carbamazepine-induced Agranulocytosis", "Leukemia", "None"]', 1, 'A black box warning for Carbamazepine. (MGH Pocket)'),
    (v_topic_id, '279: A patient taking Lamotrigine presents with a widespread erythematous rash with blistering. Diagnosis?",', '["Eczema", "Stevens-Johnson Syndrome (SJS)", "Acne", "None"]', 1, 'A black box warning for Lamotrigine. (Kaplan & Sadock)'),
    (v_topic_id, '280: A patient taking Lithium presents with a fine resting tremor. Is this a sign of toxicity?",', '["Yes, stop the drug", "No, a fine resting tremor is a common side effect at therapeutic levels. A COARSE tremor indicates toxicity.", "It means the dose is too low", "None"]', 1, 'Propranolol can be used to treat the fine tremor. (First Aid)'),
    (v_topic_id, '281: A patient taking Lithium presents with nausea, vomiting, diarrhea, coarse tremors, and confusion. Diagnosis?",', '["Gastroenteritis", "Lithium Toxicity", "NMS", "None"]', 1, 'Check a lithium level immediately. (MGH Pocket)'),
    (v_topic_id, '282: A patient presents to the ER with extreme agitation. You want to order IM Olanzapine for chemical restraint. What medication is contraindicated for concurrent IM administration?",', '["Haloperidol", "IM Lorazepam (or other IM benzos)", "Diphenhydramine", "None"]', 1, 'Due to the risk of severe respiratory depression and bradycardia. (Kaplan & Sadock)'),
    (v_topic_id, '283: A patient with bipolar disorder is manic and acutely agitated. They refuse oral meds. What is the preferred IM medication?",', '["IM Lithium", "IM Antipsychotics (e.g., Haloperidol, Olanzapine)", "IM Fluoxetine", "None"]', 1, 'Lithium is not available IM. (First Aid)'),
    (v_topic_id, '284: A patient presents with suspected Serotonin Syndrome. Which medication should be AVOIDED, as it can worsen the condition?",', '["Benzodiazepines", "Haloperidol (or other antipsychotics, as they have anticholinergic properties that inhibit sweating and can worsen hyperthermia)", "Cyproheptadine", "None"]', 1, 'Use Benzodiazepines to control agitation. (MGH Pocket)'),
    (v_topic_id, '285: A patient is diagnosed with NMS. They are rigid and hyperthermic. After stopping the antipsychotic, what medication can be used to relax the muscles?",', '["More antipsychotics", "Dantrolene (a direct acting muscle relaxant)", "Lithium", "None"]', 1, 'Bromocriptine (dopamine agonist) is also used. (Kaplan & Sadock)'),
    (v_topic_id, '286: A patient with severe, treatment-refractory depression is profoundly suicidal. What is the most effective and rapid treatment?",', '["Start another SSRI", "Electroconvulsive Therapy (ECT)", "Psychoanalysis", "None"]', 1, 'ECT has the highest response rate of any antidepressant treatment. (First Aid)'),
    (v_topic_id, '287: A pregnant woman in her 3rd trimester has severe psychotic depression and is refusing to eat, threatening the life of the fetus. What is the safest and most effective treatment?",', '["Lithium", "Electroconvulsive Therapy (ECT)", "High dose Haloperidol", "None"]', 1, 'ECT is safe and highly effective in pregnancy. (MGH Pocket)'),
    (v_topic_id, '288: A patient who ingested an unknown substance presents with dry mouth, dilated pupils, flushed skin, tachycardia, and urinary retention. Diagnosis?",', '["Cholinergic toxicity", "Anticholinergic Toxicity", "Opioid withdrawal", "None"]', 1, 'Can be caused by TCAs, antihistamines, or Jimson weed. (Kaplan & Sadock)'),
    (v_topic_id, '289: A patient presents with DUMBELS symptoms (diarrhea, urination, miosis, bronchospasm, emesis, lacrimation, salivation) after exposure to pesticides. Diagnosis?",', '["Anticholinergic toxicity", "Organophosphate Poisoning (Cholinergic Toxicity)", "Opioid overdose", "None"]', 1, 'Acetylcholinesterase inhibition leads to excessive acetylcholine. (First Aid)'),
    (v_topic_id, '290: What is the primary cause of death in Organophosphate Poisoning?",', '["Heart failure", "Respiratory failure (due to bronchospasm, bronchorrhea, and diaphragmatic paralysis)", "Liver failure", "None"]', 1, 'Atropine treats the bronchospasm; Pralidoxime treats the paralysis. (MGH Pocket)'),
    (v_topic_id, '291: A patient intentionally overdoses on a beta-blocker. They present with profound bradycardia and hypotension. What is the antidote?",', '["Atropine", "Glucagon", "Naloxone", "None"]', 1, 'Glucagon stimulates adenylate cyclase independently of the beta receptor. (Kaplan & Sadock)'),
    (v_topic_id, '292: A patient intentionally overdoses on a calcium channel blocker. They present with bradycardia and hypotension. What is a key treatment?",', '["Atropine", "High-dose Insulin and Glucose (Hyperinsulinemia-Euglycemia therapy) or IV Calcium", "Naloxone", "None"]', 1, 'Improves myocardial contractility. (First Aid)'),
    (v_topic_id, '293: A patient intentionally overdoses on Digoxin. They present with nausea, vomiting, and visual changes (yellow halos). What is the antidote?",', '["Naloxone", "Digoxin-specific antibody fragments (Digibind)", "Flumazenil", "None"]', 1, 'Monitor potassium closely, as digoxin toxicity causes hyperkalemia. (MGH Pocket)'),
    (v_topic_id, '294: A patient presents with severe agitation, hyperthermia, and hallucinations. They are found to have ingested "Jimson weed." What is the toxicity?",', '["Cholinergic", "Anticholinergic", "Serotonergic", "None"]', 1, 'Jimson weed contains atropine-like alkaloids. (Kaplan & Sadock)'),
    (v_topic_id, '295: A patient with Bipolar Disorder takes Lithium. They are started on a thiazide diuretic for hypertension. What will happen to their Lithium level?",', '["Decrease", "Increase (potential for toxicity)", "Stay the same", "None"]', 1, 'Thiazides increase proximal tubular reabsorption of sodium AND Lithium. (First Aid)'),
    (v_topic_id, '296: A patient with Bipolar Disorder takes Lithium. They take Ibuprofen for a headache. What will happen to their Lithium level?",', '["Decrease", "Increase (potential for toxicity)", "Stay the same", "None"]', 1, 'NSAIDs decrease renal blood flow, reducing Lithium clearance. (MGH Pocket)'),
    (v_topic_id, '297: A patient with Schizophrenia takes Clozapine. They start smoking cigarettes heavily. What will happen to their Clozapine level?",', '["Increase", "Decrease", "Stay the same", "None"]', 1, 'Smoking induces CYP1A2, increasing Clozapine metabolism. (Kaplan & Sadock)'),
    (v_topic_id, '298: A patient taking an MAOI for depression eats aged cheese and drinks Chianti wine. What is the primary mechanism of the resulting hypertensive crisis?",', '["Serotonin syndrome", "Tyramine displaces norepinephrine from synaptic vesicles, leading to massive sympathetic stimulation", "Direct vasoconstriction", "None"]', 1, 'A classic drug-food interaction. (First Aid)'),
    (v_topic_id, '299: A patient presents with severe depression and suicidal ideation. They have a history of multiple suicide attempts. What is the best predictor of future suicide attempts?",', '["Family history", "Past suicide attempts", "Gender", "None"]', 1, 'Past behavior is the strongest predictor of future behavior. (MGH Pocket)'),
    (v_topic_id, '300: Final Pearl: In the management of psychiatric emergencies, when a patient presents a clear and imminent danger to themselves or others, what ethical principle overrides the patient''s autonomy?",', '["Justice", "Beneficence (and the state''s police power/parens patriae authority)", "Veracity", "None"]', 1, 'Safety is the paramount concern in emergency psychiatry. (MediHelp Mastery)');
